:root {
  --cream: #fff8ee;
  --cream-soft: #fdf1e2;
  --ink: #5c4a52;
  --ink-soft: #8b737d;
  --coral: #e79a8c;
  --coral-deep: #d98279;
  --gold: #f3cf8f;
  --rose: #eab6b8;
  --sage: #aec6ab;
  --shadow: 0 18px 50px rgba(102, 68, 74, 0.18);
  --font: "Avenir Next", "Segoe UI", "Trebuchet MS", "DejaVu Sans", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #f6dcc8;
  font-family: var(--font);
  color: var(--ink);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { user-select: none; -webkit-user-select: none; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.canvas-veil {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 42%, transparent 55%, rgba(92, 62, 74, 0.18) 100%),
    linear-gradient(180deg, rgba(255, 248, 232, 0.10), transparent 30%);
  mix-blend-mode: multiply;
}

.hidden { display: none !important; }

/* ---------------------------------------------------------------- buttons */
.btn {
  appearance: none;
  border: 0;
  font-family: inherit;
  font-size: 1rem;
  letter-spacing: 0.06em;
  cursor: pointer;
  border-radius: 999px;
  padding: 0.9rem 2.1rem;
  transition: transform 0.25s cubic-bezier(.2,.8,.2,1), box-shadow 0.25s ease, background 0.25s ease, color 0.25s ease;
  will-change: transform;
}
.btn:focus-visible { outline: 3px solid rgba(231, 154, 140, 0.55); outline-offset: 3px; }
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0) scale(0.98); }

.btn.primary {
  color: #fff9f0;
  background: linear-gradient(160deg, #eda99a 0%, #dd8b82 55%, #cf7f7e 100%);
  box-shadow: 0 12px 28px rgba(201, 118, 112, 0.35), inset 0 1px 0 rgba(255,255,255,0.4);
}
.btn.primary:hover { box-shadow: 0 16px 34px rgba(201, 118, 112, 0.42), inset 0 1px 0 rgba(255,255,255,0.5); }

.btn.soft {
  color: var(--ink);
  background: rgba(255, 249, 240, 0.82);
  box-shadow: 0 6px 18px rgba(120, 88, 92, 0.12), inset 0 0 0 1px rgba(147, 116, 118, 0.14);
}
.btn.soft:hover { background: #fffaf2; }

.btn.ghost {
  color: var(--ink);
  background: rgba(255, 250, 242, 0.38);
  box-shadow: inset 0 0 0 1px rgba(126, 97, 104, 0.24);
  backdrop-filter: blur(6px);
}
.btn.ghost:hover { background: rgba(255, 250, 242, 0.62); }

.btn.text {
  background: transparent;
  color: var(--ink-soft);
  box-shadow: none;
  font-size: 0.86rem;
  padding: 0.8rem 1.2rem;
}
.btn.text:hover { color: var(--ink); transform: none; }

.btn.small { font-size: 0.8rem; padding: 0.62rem 1.15rem; }

.icon-btn {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 0;
  cursor: pointer;
  background: rgba(255, 249, 240, 0.6);
  box-shadow: 0 6px 20px rgba(110, 77, 84, 0.16), inset 0 0 0 1px rgba(255,255,255,0.55);
  backdrop-filter: blur(10px);
  display: grid;
  place-items: center;
  transition: transform 0.2s ease, background 0.2s ease;
}
.icon-btn:hover { background: rgba(255, 249, 240, 0.86); transform: scale(1.05); }
.icon-btn:active { transform: scale(0.95); }

.pause-bars {
  position: relative;
  width: 14px;
  height: 16px;
  display: block;
}
.pause-bars::before, .pause-bars::after {
  content: "";
  position: absolute;
  top: 0;
  width: 4px;
  height: 16px;
  border-radius: 2px;
  background: #7b626a;
}
.pause-bars::before { left: 1px; }
.pause-bars::after { right: 1px; }

.firefly-glyph {
  position: relative;
  width: 24px;
  height: 24px;
  display: inline-block;
  flex: none;
}
.firefly-glyph::before {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #fffbe8 0 20%, #ffe7a1 45%, #f7c978 70%, rgba(247, 201, 120, 0) 72%);
  box-shadow: 0 0 14px 4px rgba(255, 225, 150, 0.65);
}
.firefly-glyph::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 231, 166, 0.4), transparent 68%);
}
.firefly-glyph i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2px;
  height: 7px;
  margin: -3px 0 0 -1px;
  border-radius: 2px;
  background: #cfa55d;
  opacity: 0.7;
}
.firefly-glyph.small { width: 18px; height: 18px; margin-right: 5px; vertical-align: -4px; }

/* ---------------------------------------------------------------- overlays */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) 24px max(24px, env(safe-area-inset-bottom));
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.55s ease, visibility 0.55s;
  z-index: 20;
}
.overlay.show { opacity: 1; visibility: visible; }

.start-screen {
  background:
    radial-gradient(90% 75% at 50% 30%, rgba(255, 246, 228, 0.10), rgba(246, 208, 187, 0.36) 68%, rgba(219, 170, 164, 0.48) 100%);
  z-index: 30;
}

.start-inner {
  position: relative;
  text-align: center;
  max-width: 700px;
  padding: 2rem 1rem;
  transform: translateY(-1.5vh);
}

.eyebrow {
  margin: 0 0 0.8rem;
  font-size: clamp(0.64rem, 1.1vw, 0.78rem);
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: #a1787c;
  font-weight: 600;
}

.title {
  margin: 0;
  font-size: clamp(3.6rem, 11vw, 7.6rem);
  line-height: 0.95;
  font-weight: 400;
  letter-spacing: 0.015em;
  color: #fff9ee;
  text-shadow:
    0 2px 0 rgba(255, 255, 255, 0.25),
    0 10px 40px rgba(146, 91, 96, 0.32),
    0 0 80px rgba(255, 231, 188, 0.45);
}
.title span {
  display: inline-block;
  font-style: italic;
  letter-spacing: 0.02em;
  background: linear-gradient(175deg, #fff7e6 10%, #ffe5c7 45%, #f5c3ad 90%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
  filter: drop-shadow(0 8px 28px rgba(146, 91, 96, 0.28));
}

.tagline {
  margin: 1.35rem 0 2.2rem;
  font-size: clamp(0.9rem, 1.6vw, 1.08rem);
  letter-spacing: 0.11em;
  color: #8f6e73;
  font-style: italic;
}

.start-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.8rem;
  flex-wrap: wrap;
}

.start-actions .btn.primary {
  font-size: 1.02rem;
  padding: 1.02rem 2.6rem;
  letter-spacing: 0.14em;
}

.sound-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 6px;
  background: #b8897f;
  box-shadow: 0 0 0 3px rgba(184, 137, 127, 0.16);
  vertical-align: 1px;
}

.continue-hint {
  margin: 1.3rem 0 0;
  font-size: 0.74rem;
  letter-spacing: 0.13em;
  color: #a3848a;
  text-transform: lowercase;
}
.link {
  appearance: none;
  border: 0;
  background: none;
  color: #8a6770;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  cursor: pointer;
  font: inherit;
  padding: 0 0.2rem;
}
.link:hover { color: #5c4a52; }

.control-hint {
  margin: 2.5rem 0 0;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  color: rgba(105, 81, 86, 0.7);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.35rem 0.5rem;
}
.key {
  display: inline-grid;
  place-items: center;
  min-width: 1.55rem;
  height: 1.55rem;
  padding: 0 0.38rem;
  border-radius: 6px;
  background: rgba(255, 250, 240, 0.5);
  box-shadow: inset 0 0 0 1px rgba(128, 100, 104, 0.2);
  color: #7d626a;
  font-size: 0.7rem;
}
.key.wide { min-width: 2.4rem; letter-spacing: 0.08em; }
.dot-sep { opacity: 0.5; }

.start-foot {
  position: absolute;
  bottom: max(22px, env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-size: 0.6rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: rgba(110, 84, 90, 0.5);
  white-space: nowrap;
}

.menu-fireflies { position: absolute; inset: 0; pointer-events: none; }
.menu-fireflies span {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ffe9ac;
  box-shadow: 0 0 18px 6px rgba(255, 228, 157, 0.55);
  animation: drift-firefly 12s ease-in-out infinite;
  animation-delay: var(--d);
  opacity: 0;
}
@keyframes drift-firefly {
  0%, 100% { opacity: 0; transform: translate3d(0, 12px, 0) scale(0.7); }
  20% { opacity: 0.9; }
  50% { opacity: 0.55; transform: translate3d(22px, -26px, 0) scale(1.1); }
  80% { opacity: 0.85; }
}

.start-screen .start-inner { animation: rise-in 1.5s cubic-bezier(.16,.84,.3,1) both; }
@keyframes rise-in {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(-1.5vh); }
}

/* ---------------------------------------------------------------- panels */
.panel {
  position: relative;
  width: min(430px, 92vw);
  padding: 2.4rem 2rem 1.8rem;
  border-radius: 34px;
  text-align: center;
  background: linear-gradient(170deg, rgba(255, 250, 241, 0.96), rgba(250, 235, 219, 0.94));
  box-shadow: var(--shadow), inset 0 1px 0 #fff;
  animation: panel-in 0.6s cubic-bezier(.16,.84,.3,1) both;
}
@keyframes panel-in {
  from { opacity: 0; transform: translateY(18px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.pause-screen, .settings-screen, .complete-screen {
  background: rgba(84, 63, 72, 0.22);
  backdrop-filter: blur(9px) saturate(0.9);
}

.panel-title {
  margin: 0.1rem 0 0.7rem;
  font-size: 2.15rem;
  font-weight: 400;
  font-style: italic;
  letter-spacing: 0.03em;
  color: #6a5259;
}

.panel-actions {
  display: flex;
  flex-direction: column;
  gap: 0.62rem;
  margin-top: 1.5rem;
}
.panel-actions .btn { width: 100%; }

.panel-note {
  margin: 1.35rem 0 0;
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  color: #ad9094;
  text-transform: lowercase;
}

/* sliders */
.slider-row {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "label value" "range range";
  gap: 0.4rem 1rem;
  margin: 1.15rem 0 1.5rem;
  text-align: left;
  align-items: center;
}
.slider-row label {
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #93757c;
  grid-area: label;
}
.slider-value {
  grid-area: value;
  font-size: 0.72rem;
  color: #b19194;
  font-variant-numeric: tabular-nums;
}
.range {
  grid-area: range;
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 26px;
  background: transparent;
  cursor: pointer;
  margin: 0;
}
.range::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 6px;
  background: linear-gradient(90deg, #e8b6a8, #f3d7ad);
  box-shadow: inset 0 1px 2px rgba(120, 85, 85, 0.16);
}
.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  margin-top: -7px;
  border-radius: 50%;
  background: #fffaf3;
  box-shadow: 0 3px 9px rgba(139, 98, 95, 0.32), inset 0 0 0 5px #eaa596;
  transition: transform 0.15s ease;
}
.range:active::-webkit-slider-thumb { transform: scale(1.12); }
.range::-moz-range-track {
  height: 6px;
  border-radius: 6px;
  background: linear-gradient(90deg, #e8b6a8, #f3d7ad);
}
.range::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 50%;
  background: #fffaf3;
  box-shadow: 0 3px 9px rgba(139, 98, 95, 0.32), inset 0 0 0 5px #eaa596;
}

.mute-toggle {
  width: 100%;
  margin: 0.2rem 0 1rem;
  font-size: 0.8rem;
  letter-spacing: 0.1em;
}
.mute-toggle .mute-icon {
  display: inline-block;
  width: 22px;
  color: #d98279;
  font-size: 1.05rem;
  font-style: normal;
}
.mute-toggle.muted { background: rgba(232, 196, 187, 0.55); color: #8b666b; }
.mute-toggle.muted .mute-icon { opacity: 0.45; text-decoration: line-through; }

/* ---------------------------------------------------------------- complete */
.complete-panel { padding-top: 2rem; }
.complete-sub {
  margin: 0 0 1.1rem;
  font-size: 0.86rem;
  font-style: italic;
  letter-spacing: 0.04em;
  color: #9c7d82;
}
.complete-count {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin: 0.2rem 0 1.7rem;
  padding: 0.5rem 1.05rem;
  border-radius: 999px;
  background: rgba(255, 248, 235, 0.8);
  box-shadow: inset 0 0 0 1px rgba(193, 157, 137, 0.25);
  font-size: 0.8rem;
  letter-spacing: 0.07em;
  color: #8d6f72;
}
.complete-panel .btn.primary { width: 100%; }
.complete-panel .btn.text { margin-top: 0.35rem; }

.bloom-mark {
  position: relative;
  width: 82px;
  height: 82px;
  margin: 0 auto 1.1rem;
  animation: bloom-sway 7s ease-in-out infinite;
}
.bloom-mark span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 30px;
  height: 46px;
  margin: -42px 0 0 -15px;
  border-radius: 50% 50% 46% 46%;
  background: linear-gradient(180deg, #ffeccd, #f3b9ad);
  transform-origin: 50% 100%;
  opacity: 0.92;
}
.bloom-mark span:nth-child(1) { transform: rotate(0deg); }
.bloom-mark span:nth-child(2) { transform: rotate(90deg); }
.bloom-mark span:nth-child(3) { transform: rotate(180deg); }
.bloom-mark span:nth-child(4) { transform: rotate(270deg); }
.bloom-mark i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 22px;
  margin: -11px 0 0 -11px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fffdf0, #ffe4a2 60%, #edc27c);
  box-shadow: 0 0 24px 8px rgba(255, 227, 158, 0.6);
}
@keyframes bloom-sway {
  0%, 100% { transform: rotate(-5deg) scale(0.99); }
  50% { transform: rotate(5deg) scale(1.03); }
}

