export const TAU = Math.PI * 2;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const smoothstep = (a, b, v) => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const sign = (v) => (v < 0 ? -1 : v > 0 ? 1 : 0);

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hash(n) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453123;
  return x - Math.floor(x);
}

export function hexToRgb(hex) {
  let h = hex.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  const n = parseInt(h, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

export function rgba(hex, a = 1) {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r}, ${g}, ${b}, ${a})`;
}

export function mix(hexA, hexB, t) {
  const a = hexToRgb(hexA);
  const b = hexToRgb(hexB);
  const r = Math.round(lerp(a.r, b.r, t));
  const g = Math.round(lerp(a.g, b.g, t));
  const b2 = Math.round(lerp(a.b, b.b, t));
  return `rgb(${r}, ${g}, ${b2})`;
}

export function shade(hex, amount) {
  const { r, g, b } = hexToRgb(hex);
  const f = (v) => Math.round(amount < 0 ? v * (1 + amount) : v + (255 - v) * amount);
  return `rgb(${f(r)}, ${f(g)}, ${f(b)})`;
}

export function roundedRect(ctx, x, y, w, h, r) {
  const rr = typeof r === 'number' ? Math.min(r, w / 2, h / 2) : r;
  ctx.beginPath();
  if (typeof rr === 'object') {
    const [tl, tr, br, bl] = rr;
    ctx.moveTo(x + tl, y);
    ctx.lineTo(x + w - tr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + tr);
    ctx.lineTo(x + w, y + h - br);
    ctx.quadraticCurveTo(x + w, y + h, x + w - br, y + h);
    ctx.lineTo(x + bl, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - bl);
    ctx.lineTo(x, y + tl);
    ctx.quadraticCurveTo(x, y, x + tl, y);
  } else {
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
  }
  ctx.closePath();
}

export function ellipse(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.max(0.01, rx), Math.max(0.01, ry), rot, 0, TAU);
}

export function overlap(a, b, pad = 0) {
  return (
    a.x + pad < b.x + b.w &&
    a.x + a.w - pad > b.x &&
    a.y + pad < b.y + b.h &&
    a.y + a.h - pad > b.y
  );
}

export function pointInRect(px, py, r) {
  return px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;
}

export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInOutSine = (t) => -(Math.cos(Math.PI * t) - 1) / 2;

import { TAU, clamp, rgba, hash, ellipse } from './util.js';

/**
 * Tiny world-space particle system. Particles are spawned in level coordinates
 * and rendered inside the camera transform.
 */
export class FX {
  constructor() {
    this.list = [];
    this.max = 460;
  }

  spawn(p) {
    if (this.list.length >= this.max) this.list.shift();
    this.list.push({
      x: 0, y: 0, vx: 0, vy: 0, life: 1, maxLife: 1, size: 3,
      color: '#ffe9a6', type: 'dot', gravity: 0, drag: 0.9, rot: 0, vr: 0,
      fade: true, additive: true, ...p,
    });
  }

  burst(x, y, opts = {}) {
    const {
      color = '#ffe9a6', count = 10, speed = 90, spread = TAU,
      life = 0.9, size = 3.2, gravity = 80, type = 'dot', additive = true,
      angle = -Math.PI / 2, jitter = 0.35, drag = 0.92,
    } = opts;
    for (let i = 0; i < count; i++) {
      const a = angle + (Math.random() - 0.5) * spread;
      const s = speed * (0.35 + Math.random() * 0.9);
      this.spawn({
        x: x + (Math.random() - 0.5) * 10,
        y: y + (Math.random() - 0.5) * 10,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: life * (0.65 + Math.random() * 0.7),
        maxLife: life,
        size: size * (0.6 + Math.random() * 0.8),
        color, type, gravity, additive, drag,
        rot: Math.random() * TAU,
        vr: (Math.random() - 0.5) * (type === 'petal' ? 6 : 2) * jitter,
      });
    }
  }

  ring(x, y, color = '#ffe9b0', size = 14, life = 0.7) {
    this.spawn({ x, y, type: 'ring', color, size, life, maxLife: life, vx: 0, vy: 0, additive: true });
  }

  petalFall(x, y, color = '#f6c9c4') {
    this.spawn({
      x, y,
      vx: -20 + Math.random() * 40,
      vy: 16 + Math.random() * 26,
      life: 4 + Math.random() * 2,
      maxLife: 6,
      size: 3 + Math.random() * 2.6,
      color, type: 'petal', gravity: 2, additive: false, drag: 0.995,
      rot: Math.random() * TAU, vr: (Math.random() - 0.5) * 2.4,
    });
  }

  update(dt) {
    const l = this.list;
    for (let i = l.length - 1; i >= 0; i--) {
      const p = l[i];
      p.life -= dt;
      if (p.life <= 0) {
        l.splice(i, 1);
        continue;
      }
      p.vy += p.gravity * dt;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy *= Math.pow(p.drag, dt * 60);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.vr * dt;
      if (p.type === 'petal') {
        p.x += Math.sin(p.life * 2.6 + p.rot) * 10 * dt;
      }
    }
  }

  draw(ctx) {
    const l = this.list;
    if (!l.length) return;

    // Soft additive layer (glows, sparkles, rings)
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < l.length; i++) {
      const p = l[i];
      if (!p.additive && p.type !== 'ring') continue;
      const t = clamp(p.life / p.maxLife, 0, 1);
      const alpha = p.fade ? Math.min(1, t * 1.6) : 1;

      if (p.type === 'ring') {
        const prog = 1 - t;
        ctx.globalAlpha = alpha * 0.55;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2.2 * t + 0.4;
        ellipse(ctx, p.x, p.y, p.size + prog * 34, (p.size + prog * 34) * 0.55);
        ctx.stroke();
      } else if (p.type === 'sparkle') {
        ctx.globalAlpha = alpha;
        const s = p.size * (0.6 + t);
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, s * 4);
        g.addColorStop(0, p.color);
        g.addColorStop(0.35, rgba(p.color, 0.5));
        g.addColorStop(1, rgba(p.color, 0));
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(p.x, p.y, s * 4, 0, TAU);
        ctx.fill();
        ctx.strokeStyle = rgba('#fffdf0', 0.85);
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.moveTo(p.x - s * 2.2, p.y);
        ctx.lineTo(p.x + s * 2.2, p.y);
        ctx.moveTo(p.x, p.y - s * 2.2);
        ctx.lineTo(p.x, p.y + s * 2.2);
        ctx.stroke();
      } else {
        const s = p.size * (0.45 + t * 0.8);
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, s * 3.2);
        g.addColorStop(0, rgba('#fffdf3', alpha));
        g.addColorStop(0.28, rgba(p.color, alpha * 0.9));
        g.addColorStop(1, rgba(p.color, 0));
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(p.x, p.y, s * 3.2, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();

    // Non-additive layer (petals, dust)
    ctx.save();
    for (let i = 0; i < l.length; i++) {
      const p = l[i];
      if (p.additive || p.type === 'ring') continue;
      const t = clamp(p.life / p.maxLife, 0, 1);
      const alpha = Math.min(1, t * 2.4);
      ctx.globalAlpha = alpha;

      if (p.type === 'petal') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, p.size, p.size * 0.55, 0, 0, TAU);
        ctx.fill();
        ctx.restore();
      } else if (p.type === 'leaf') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.moveTo(0, -p.size);
        ctx.quadraticCurveTo(p.size, -p.size * 0.2, 0, p.size);
        ctx.quadraticCurveTo(-p.size, -p.size * 0.2, 0, -p.size);
        ctx.fill();
        ctx.restore();
      } else {
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size * 2);
        g.addColorStop(0, rgba(p.color, alpha * 0.5));
        g.addColorStop(1, rgba(p.color, 0));
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * 2, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();
  }
}

import { TAU, rgba, mix, clamp, hash, mulberry32 } from './util.js';

/**
 * Layered, hand-drawn feeling parallax sky. Drawn in CSS pixels, before the
 * world transform, so it always fills the screen.
 */
export class Background {
  constructor(theme, seed = 1) {
    this.theme = theme;
    const rng = mulberry32(seed * 7919 + 3);
    this.theme = theme;
    this.clouds = Array.from({ length: 7 }, (_, i) => ({
      x: rng() * 2600,
      y: 60 + rng() * 240,
      s: 0.55 + rng() * 0.85,
      speed: 2.4 + rng() * 3.6,
      alpha: 0.4 + rng() * 0.4,
      puffs: 3 + Math.floor(rng() * 3),
    }));
    this.stars = Array.from({ length: 90 }, () => ({
      x: rng(),
      y: rng() * 0.55,
      size: 0.6 + rng() * 1.6,
      phase: rng() * TAU,
      speed: 0.4 + rng() * 1.1,
    }));
    this.birdSeed = rng() * 100;
    this.treeSeed = Math.floor(rng() * 999);
    this.foreground = Array.from({ length: 30 }, (_, i) => ({
      i,
      y: 0.93 + rng() * 0.09,
      h: 18 + rng() * 34,
      lean: (rng() - 0.5) * 0.5,
    }));
  }

  hillPath(ctx, w, h, camOffset, baseY, amp, freq, color, alpha = 1) {
    ctx.beginPath();
    ctx.moveTo(-30, h + 30);
    const step = 16;
    for (let x = -30; x <= w + 30; x += step) {
      const xx = x + camOffset;
      const y =
        baseY -
        (Math.sin(xx * freq) * amp +
          Math.sin(xx * freq * 2.37 + 1.9) * amp * 0.42 +
          Math.sin(xx * freq * 0.51 + 4.2) * amp * 0.72);
      ctx.lineTo(x, y);
    }
    ctx.lineTo(w + 30, h + 30);
    ctx.closePath();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  cloud(ctx, x, y, scale, alpha, color, puffs) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.fillStyle = color;
    for (let i = 0; i < puffs; i++) {
      const px = (i - (puffs - 1) / 2) * 34;
      const py = Math.sin(i * 1.7) * 7;
      const r = 24 + hash(i + puffs * 3.1) * 18;
      ctx.beginPath();
      ctx.ellipse(px, py, r * 1.18, r * 0.72, 0, 0, TAU);
      ctx.fill();
    }
    ctx.beginPath();
    ctx.ellipse(0, 13, 56, 15, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  tree(ctx, x, baseY, scale, color, dark, sway) {
    ctx.save();
    ctx.translate(x, baseY);
    ctx.rotate(sway * 0.012);
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(-4 * scale, -48 * scale, 8 * scale, 50 * scale, 4) : ctx.rect(-4, -48 * scale, 8 * scale, 50 * scale);
    ctx.fill();
    ctx.fillStyle = color;
    const blobs = [
      [0, -66, 30, 26],
      [-22, -54, 22, 19],
      [22, -55, 21, 18],
      [-4, -84, 20, 17],
    ];
    for (const [bx, by, rx, ry] of blobs) {
      ctx.beginPath();
      ctx.ellipse(bx * scale, by * scale, rx * scale, ry * scale, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  bush(ctx, x, y, scale, color, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    const puffs = 3;
    for (let i = 0; i < puffs; i++) {
      const px = (i - 1) * 18 * scale;
      const r = (15 + hash(i * 4.7 + x) * 7) * scale;
      ctx.beginPath();
      ctx.ellipse(x + px, y - r * 0.3, r * 1.25, r * 0.8, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  draw(ctx, cam, w, h, t, zoom) {
    const th = this.theme;
    const camX = cam.x * zoom;
    const camY = cam.y * zoom;

    ctx.save();
    // ---- sky
    const sky = ctx.createLinearGradient(0, 0, 0, h * 1.05);
    sky.addColorStop(0, th.sky[0]);
    sky.addColorStop(0.52, th.sky[1]);
    sky.addColorStop(1, th.sky[2]);
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    // ---- stars
    if (th.stars > 0) {
      for (const s of this.stars) {
        const tw = 0.45 + 0.55 * (0.5 + 0.5 * Math.sin(t * s.speed + s.phase));
        ctx.globalAlpha = clamp(th.stars * tw * 0.9, 0, 1);
        ctx.fillStyle = '#fff3d8';
        const x = s.x * w;
        const y = s.y * h * 0.82;
        ctx.beginPath();
        ctx.arc(x, y, s.size, 0, TAU);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    // ---- sun / moon
    const orb = th.orb;
    if (orb) {
      const ox = w * orb.x - camX * 0.006 + Math.sin(t * 0.03) * 10;
      const oy = h * orb.y - camY * 0.02;
      const radius = orb.r * Math.min(1.25, w / 1100);
      const glow = ctx.createRadialGradient(ox, oy, radius * 0.2, ox, oy, radius * 5.2);
      glow.addColorStop(0, rgba(orb.glow, 0.55));
      glow.addColorStop(0.35, rgba(orb.glow, 0.2));
      glow.addColorStop(1, rgba(orb.glow, 0));
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(ox, oy, radius * 5.2, 0, TAU);
      ctx.fill();
      const disc = ctx.createRadialGradient(ox - radius * 0.25, oy - radius * 0.3, radius * 0.1, ox, oy, radius);
      disc.addColorStop(0, '#fffdf2');
      disc.addColorStop(0.7, orb.color);
      disc.addColorStop(1, rgba(orb.color, 0.75));
      ctx.fillStyle = disc;
      ctx.beginPath();
      ctx.arc(ox, oy, radius, 0, TAU);
      ctx.fill();

      if (orb.crescent) {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.beginPath();
        ctx.arc(ox + radius * 0.42, oy - radius * 0.18, radius * 0.92, 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
    }

    // ---- soft clouds
    const cloudColor = mix(th.cloud, th.sky[1], th.dusk ? 0.45 : 0.15);
    for (const c of this.clouds) {
      const span = w + 700;
      let x = (c.x + t * c.speed - camX * 0.05) % span;
      if (x < 0) x += span;
      x -= 350;
      const y = c.y * (h / 720) - camY * 0.03;
      this.cloud(ctx, x, y, c.s * Math.min(1.15, w / 900), c.alpha * th.cloudAlpha, cloudColor, c.puffs);
    }

    // ---- birds
    if (th.birds) {
      ctx.strokeStyle = rgba(th.birdColor || '#8d7b86', 0.35);
      ctx.lineWidth = 1.6;
      ctx.lineCap = 'round';
      for (let i = 0; i < 3; i++) {
        const speed = 12 + i * 5;
        let x = ((t * speed + i * 420 + this.birdSeed * 10) % (w + 340)) - 170;
        const y = h * (0.14 + i * 0.055) + Math.sin(t * 0.5 + i) * 8 - camY * 0.02;
        const flap = Math.sin(t * 2.2 + i * 1.7) * 4;
        ctx.beginPath();
        ctx.moveTo(x - 9, y + flap);
        ctx.quadraticCurveTo(x - 4, y - 3, x, y);
        ctx.quadraticCurveTo(x + 4, y - 3, x + 9, y + flap);
        ctx.stroke();
      }
    }

    // ---- mist glow at horizon
    if (th.mist > 0.05) {
      const hy = h * 0.6 + camY * 0.02;
      const g = ctx.createLinearGradient(0, hy - 100, 0, hy + 130);
      g.addColorStop(0, rgba(th.mistColor, 0));
      g.addColorStop(0.5, rgba(th.mistColor, 0.28 * th.mist));
      g.addColorStop(1, rgba(th.mistColor, 0));
      ctx.fillStyle = g;
      ctx.fillRect(0, hy - 100, w, 230);
    }

    // ---- water horizon (creek)
    if (th.water) {
      const wy = th.waterWorldY * zoom - camY;
      if (wy < h + 80) {
        const wg = ctx.createLinearGradient(0, wy - 20, 0, wy + 260);
        wg.addColorStop(0, rgba(th.water, 0.55));
        wg.addColorStop(0.3, rgba(th.water, 0.75));
        wg.addColorStop(1, rgba(th.waterDeep || th.water, 0.92));
        ctx.fillStyle = wg;
        ctx.fillRect(0, wy, w, h - wy + 40);
        // shimmer
        ctx.strokeStyle = rgba('#ffffff', 0.22);
        ctx.lineWidth = 1.2;
        for (let i = 0; i < 9; i++) {
          const ly = wy + 22 + i * 13;
          const off = Math.sin(t * 0.7 + i * 1.4) * 24;
          ctx.beginPath();
          ctx.moveTo(off + (i * 87) % Math.max(1, w), ly);
          ctx.lineTo(off + (i * 87) % Math.max(1, w) + 60, ly);
          ctx.stroke();
        }
        // distant reflections
        ctx.globalAlpha = 0.16;
        ctx.fillStyle = '#fff6e4';
        for (let i = 0; i < 5; i++) {
          const rx = (i * 173 + Math.sin(t * 0.2 + i) * 10) % w;
          ctx.beginPath();
          ctx.ellipse(rx, wy + 30 + i * 17, 22, 3, 0, 0, TAU);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
      }
    }

    // ---- far hills
    const horizon = h * 0.55 + camY * 0.035;
    const shift = camX * 0.1;
    this.hillPath(ctx, w, h, shift, horizon + h * 0.1, h * 0.035, 0.0032, th.hillFar, 0.85);
    this.hillPath(ctx, w, h, camX * 0.2, horizon + h * 0.175, h * 0.045, 0.0041, th.hillMid, 0.92);

    // ---- mid tree line
    const spacing = 230;
    const tf = 0.34;
    const off = camX * tf;
    const start = Math.floor(off / spacing) - 2;
    const count = Math.ceil(w / spacing) + 5;
    for (let i = start; i < start + count; i++) {
      if (hash(i * 1.37 + this.treeSeed) < 0.24) continue;
      const x = i * spacing - off + (hash(i) - 0.5) * 60;
      const scale = 0.62 + hash(i * 2.1) * 0.5;
      const baseY = horizon + h * 0.255 + (hash(i * 3.3) - 0.5) * 14;
      if (x < -120 || x > w + 120) continue;
      this.tree(ctx, x, baseY, scale, th.treeColor, th.treeDark || th.hillMid, Math.sin(t * 0.4 + i));
    }

    // ---- near bushes
    const bushSpacing = 168;
    const bf = 0.56;
    const boff = camX * bf;
    const bstart = Math.floor(boff / bushSpacing) - 2;
    const bcount = Math.ceil(w / bushSpacing) + 5;
    for (let i = bstart; i < bstart + bcount; i++) {
      const x = i * bushSpacing - boff + (hash(i * 1.9) - 0.5) * 40;
      if (x < -80 || x > w + 80) continue;
      const baseY = h * 0.78 + (hash(i * 2.7) - 0.5) * 22 + camY * 0.05;
      const scale = 0.7 + hash(i * 4.1) * 0.55;
      this.bush(ctx, x, baseY, scale, th.bushColor, 0.5);
    }

    // ---- near hill silhouette
    this.hillPath(ctx, w, h, camX * 0.62, h * 0.86 + camY * 0.06, h * 0.04, 0.0052, th.hillNear, 0.95);

    // ---- scarce drifting pollen / light motes (background)
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 16; i++) {
      const x = (hash(i * 3.1) * w + t * (3 + (i % 3)) - camX * 0.16) % (w + 40);
      const y = (hash(i * 7.7) * h * 0.7 + Math.sin(t * 0.3 + i) * 14 + camY * 0.04) % h;
      const a = 0.18 + 0.14 * Math.sin(t * 0.9 + i);
      const r = 1.2 + hash(i) * 2;
      const g = ctx.createRadialGradient(x, y, 0, x, y, r * 4);
      g.addColorStop(0, rgba(th.mote || '#ffe9b0', a));
      g.addColorStop(1, rgba(th.mote || '#ffe9b0', 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, r * 4, 0, TAU);
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';

    // ---- foreground grass silhouettes
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.fillStyle = th.foregroundColor || th.hillNear;
    const fgSpacing = 88;
    const foff = camX * 1.12;
    const fstart = Math.floor(foff / fgSpacing) - 2;
    for (let i = fstart; i < fstart + Math.ceil(w / fgSpacing) + 4; i++) {
      if (hash(i * 5.3) < 0.32) continue;
      const x = i * fgSpacing - foff + hash(i) * 50;
      const baseY = h + 16;
      const hh = 24 + hash(i * 2.2) * 48;
      if (x < -40 || x > w + 40) continue;
      const sway = Math.sin(t * 1.1 + i * 0.7) * 9;
      ctx.beginPath();
      ctx.moveTo(x - 10, baseY);
      ctx.quadraticCurveTo(x - 7 + sway * 0.4, baseY - hh * 0.6, x - 2 + sway, baseY - hh);
      ctx.quadraticCurveTo(x - 2 + sway * 0.3, baseY - hh * 0.55, x + 4, baseY);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    ctx.restore();
  }
}

import { clamp, mulberry32 } from './util.js';

const mtof = (m) => 440 * Math.pow(2, (m - 69) / 12);

/**
 * A tiny generative music box: soft piano-ish plucks, warm pads, bass,
 * wind / water / rain ambience, birds, and gentle UI sounds.
 * Everything is synthesised, so the game stays a small static bundle.
 */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.musicVolume = 0.62;
    this.sfxVolume = 0.78;
    this.muted = false;

    this.musicConfig = null;
    this.pendingMusic = null;
    this.switchAt = 0;
    this.step = 0;
    this.nextNote = 0;
    this.lastChord = null;
    this.melodyMidi = 69;

    this.ambience = { wind: 0.4, birds: 0.5, rain: 0, water: 0 };
    this.birdTimer = 4;
    this.rainTimer = 2;
    this.rng = mulberry32(20260413);
  }

  init() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this._buildGraph();
      this.ready = true;
      if (this.pendingMusic) {
        this.musicConfig = this.pendingMusic;
        this.pendingMusic = null;
        this.step = 0;
        this.nextNote = this.ctx.currentTime + 0.15;
        this._fadeMusicTo(this.musicVolume, 1.5);
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  _buildGraph() {
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 1;

    this.compressor = ctx.createDynamicsCompressor();
    this.compressor.threshold.value = -20;
    this.compressor.knee.value = 24;
    this.compressor.ratio.value = 3;
    this.compressor.attack.value = 0.02;
    this.compressor.release.value = 0.35;

    this.master.connect(this.compressor);
    this.compressor.connect(ctx.destination);

    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = 0;
    this.musicBus.connect(this.master);

    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = this.sfxVolume;
    this.sfxBus.connect(this.master);

    this.ambientGain = ctx.createGain();
    this.ambientGain.gain.value = 0.0001;
    this.ambientGain.connect(this.master);

    // reverb
    this.reverb = ctx.createConvolver();
    this.reverb.buffer = this._impulse(2.6, 2.4);
    this.reverbWet = ctx.createGain();
    this.reverbWet.gain.value = 0.22;
    this.reverb.connect(this.reverbWet);
    this.reverbWet.connect(this.master);
    this.reverbIn = ctx.createGain();
    this.reverbIn.gain.value = 1;
    this.reverbIn.connect(this.reverb);

    this.noise = this._noiseBuffer(2.5);
  }

  _impulse(seconds, decay) {
    const ctx = this.ctx;
    const rate = ctx.sampleRate;
    const len = Math.floor(rate * seconds);
    const buf = ctx.createBuffer(2, len, rate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buf.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        const env = Math.pow(1 - t, decay);
        data[i] = (Math.random() * 2 - 1) * env * (i < 300 ? i / 300 : 1);
      }
    }
    return buf;
  }

  _noiseBuffer(seconds) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 2.4;
    }
    // make it loop smoothly
    const fade = 800;
    for (let i = 0; i < fade; i++) {
      const k = i / fade;
      data[i] *= k;
      data[len - 1 - i] *= k;
    }
    return buf;
  }

  _ambientLoop(type) {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    const gain = ctx.createGain();
    gain.gain.value = 0.0001;
    if (type === 'wind') {
      filter.type = 'lowpass';
      filter.frequency.value = 420;
      filter.Q.value = 0.7;
    } else if (type === 'water') {
      filter.type = 'bandpass';
      filter.frequency.value = 720;
      filter.Q.value = 1.1;
    } else {
      filter.type = 'highpass';
      filter.frequency.value = 3200;
    }
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.ambientGain);
    src.start();
    return { src, filter, gain };
  }

  _ensureAmbient() {
    if (this.ambientNodes) return;
    if (!this.ctx) return;
    this.ambientNodes = {
      wind: this._ambientLoop('wind'),
      water: this._ambientLoop('water'),
      rain: this._ambientLoop('rain'),
    };
    const ctx = this.ctx;
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 160;
    lfo.connect(lfoGain);
    lfoGain.connect(this.ambientNodes.wind.filter.frequency);
    lfo.start();
  }

  setVolumes({ music, sfx } = {}) {
    if (typeof music === 'number') this.musicVolume = clamp(music, 0, 1);
    if (typeof sfx === 'number') this.sfxVolume = clamp(sfx, 0, 1);
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this._fadeMusicTo(this.musicVolume, 0.4);
    this.sfxBus.gain.setTargetAtTime(this.sfxVolume, now, 0.08);
    this._ambientTargets();
  }

  setMuted(muted) {
    this.muted = !!muted;
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setTargetAtTime(this.muted ? 0 : 1, now, 0.06);
  }

  _fadeMusicTo(value, seconds) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.musicBus.gain.cancelScheduledValues(now);
    this.musicBus.gain.setTargetAtTime(value, now, Math.max(0.08, seconds / 3.2));
  }

  /** Switch the generative progression, with a soft level-to-level fade. */
  setMusic(config, fade = 1.6) {
    this.pendingMusic = config;
    if (!this.ctx) return;
    this._ensureAmbient();
    this.ctx.resume().catch(() => {});
    const now = this.ctx.currentTime;
    this.musicBus.gain.cancelScheduledValues(now);
    this.musicBus.gain.setTargetAtTime(0, now, 0.35);
    this.switchAt = now + Math.max(0.45, fade * 0.45);

    const target = { ...this.ambience };
    this._ambientTargets();
    void target;
  }

  setAmbience(cfg = {}) {
    this.ambience = { ...this.ambience, ...cfg };
    this._ambientTargets();
  }

  _ambientTargets() {
    if (!this.ctx || !this.ambientNodes) return;
    const now = this.ctx.currentTime;
    const base = this.sfxVolume;
    const n = this.ambientNodes;
    n.wind.gain.gain.setTargetAtTime(Math.max(0.0001, this.ambience.wind * 0.16 * base), now, 1.2);
    n.water.gain.gain.setTargetAtTime(Math.max(0.0001, this.ambience.water * 0.1 * base), now, 1.2);
    n.rain.gain.gain.setTargetAtTime(Math.max(0.0001, this.ambience.rain * 0.055 * base), now, 1.4);
  }

  update(dt) {
    if (!this.ctx || this.ctx.state !== 'running') return;

    // swap progression after fade-out
    if (this.switchAt && this.ctx.currentTime >= this.switchAt && this.pendingMusic) {
      this.musicConfig = this.pendingMusic;
      this.pendingMusic = null;
      this.switchAt = 0;
      this.step = 0;
      this.nextNote = this.ctx.currentTime + 0.1;
      this._fadeMusicTo(this.musicVolume, 1.8);
    }

    this._scheduleMusic();
    this._ambientEvents(dt);
  }

  _scheduleMusic() {
    const cfg = this.musicConfig;
    if (!cfg) return;
    const now = this.ctx.currentTime;
    if (this.nextNote < now - 1) this.nextNote = now + 0.05;
    if (this.nextNote === 0) this.nextNote = now + 0.1;

    let guard = 0;
    while (this.nextNote < now + 0.55 && guard++ < 40) {
      this._musicStep(this.step, this.nextNote, cfg);
      this.nextNote += 30 / cfg.tempo; // eighth note
      this.step++;
    }
  }

  _musicStep(step, t, cfg) {
    const bar = Math.floor(step / 16);
    const s = step % 16;
    const chord = cfg.chords[bar % cfg.chords.length];
    const base = cfg.base;

    if (s === 0) {
      const noteCount = chord.length;
      for (let i = 0; i < noteCount; i++) {
        const midi = base + chord[i] - 12 * (i === 0 ? 0 : 1) + (i === 0 ? 0 : 0);
        this._pad(midi + (i === 0 ? 0 : 0), t + i * 0.03, 4.6, i === 0 ? 0.045 : 0.03);
      }
      this._bass(base + chord[0] - 24, t, 0.075, 4.2);
      this.lastChord = chord;
    }

    // gentle arpeggio
    const arpSteps = [0, 3, 6, 8, 11, 14];
    if (arpSteps.includes(s) && this.rng() < 0.62) {
      const ci = Math.floor(this.rng() * chord.length);
      const octave = this.rng() < 0.3 ? 12 : 0;
      const midi = base + chord[ci] + octave + (s >= 8 ? 12 : 0);
      this._piano(midi, t, 1.5 + this.rng() * 0.9, 0.085 + this.rng() * 0.03, ci % 2 ? 0.35 : -0.35);
    }

    // sparse melody
    if ((s === 4 || s === 10 || s === 14) && this.rng() < 0.32) {
      const scale = cfg.scale;
      let midi = base + 24 + scale[Math.floor(this.rng() * scale.length)] + (this.rng() < 0.35 ? 12 : 0);
      if (Math.abs(midi - this.melodyMidi) > 7) midi = this.melodyMidi + (midi > this.melodyMidi ? 2 : -2);
      this.melodyMidi = midi;
      this._piano(midi, t + 0.02, 2.2, 0.065, 0.15);
      this._piano(midi + 12, t + 0.02, 1.1, 0.018, -0.3);
    }

    if (s === 15 && this.rng() < 0.18) {
      const midi = base + 36 + cfg.scale[Math.floor(this.rng() * cfg.scale.length)];
      this._bell(midi, t + 0.1, 0.035, 1.6);
    }
  }

  _piano(midi, t, dur, vel, pan = 0) {
    const ctx = this.ctx;
    const f = mtof(midi);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const pn = ctx.createStereoPanner();
    pn.pan.value = pan;
    g.connect(pn);
    pn.connect(this.musicBus);
    const send = ctx.createGain();
    send.gain.value = 0.5;
    pn.connect(send);
    send.connect(this.reverbIn);

    const harmonics = [[1, 1, 'sine'], [2, 0.3, 'sine'], [3.99, 0.08, 'triangle']];
    for (const [mul, amp, type] of harmonics) {
      const o = ctx.createOscillator();
      o.type = type;
      o.frequency.setValueAtTime(f * mul, t);
      o.detune.value = (mul === 1 ? (this.rng() - 0.5) * 4 : 0);
      const og = ctx.createGain();
      og.gain.value = amp;
      o.connect(og);
      og.connect(g);
      o.start(t);
      o.stop(t + dur + 0.05);
    }
  }

  _pad(midi, t, dur, vel) {
    const ctx = this.ctx;
    const f = mtof(midi);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 1.3);
    g.gain.setValueAtTime(vel, t + dur * 0.55);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 1100;
    lp.Q.value = 0.4;
    g.connect(lp);
    lp.connect(this.musicBus);
    const send = ctx.createGain();
    send.gain.value = 0.7;
    lp.connect(send);
    send.connect(this.reverbIn);

    for (const det of [-5, 5]) {
      const o = ctx.createOscillator();
      o.type = 'triangle';
      o.frequency.value = f;
      o.detune.value = det;
      const og = ctx.createGain();
      og.gain.value = 0.5;
      o.connect(og);
      og.connect(g);
      o.start(t);
      o.stop(t + dur + 0.1);
    }
  }

  _bass(midi, t, vel, dur) {
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = mtof(midi);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 0.14);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g);
    g.connect(this.musicBus);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  _bell(midi, t, vel, dur) {
    const ctx = this.ctx;
    const f = mtof(midi);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = f;
    const o2 = ctx.createOscillator();
    o2.type = 'sine';
    o2.frequency.value = f * 2.01;
    const g2 = ctx.createGain();
    g2.gain.value = 0.25;
    o.connect(g);
    o2.connect(g2);
    g2.connect(g);
    const send = ctx.createGain();
    send.gain.value = 0.8;
    g.connect(this.musicBus);
    g.connect(send);
    send.connect(this.reverbIn);
    o.start(t);
    o2.start(t);
    o.stop(t + dur + 0.05);
    o2.stop(t + dur + 0.05);
  }

  // ------------------------------------------------------------- effects
  _sfxBlip({ f0 = 440, f1 = 660, dur = 0.18, type = 'sine', vel = 0.14, pan = 0, delay = 0 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f0, t);
    o.frequency.exponentialRampToValueAtTime(Math.max(30, f1), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const pn = ctx.createStereoPanner();
    pn.pan.value = pan;
    o.connect(g);
    g.connect(pn);
    pn.connect(this.sfxBus);
    const send = ctx.createGain();
    send.gain.value = 0.35;
    pn.connect(send);
    send.connect(this.reverbIn);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  _sfxNoise({ dur = 0.15, vel = 0.08, freq = 900, type = 'lowpass', q = 0.8 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vel, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f);
    f.connect(g);
    g.connect(this.sfxBus);
    src.start(t, Math.random() * 1.5);
    src.stop(t + dur + 0.05);
  }

  click() {
    this._sfxBlip({ f0: 720, f1: 860, dur: 0.09, vel: 0.05, type: 'sine' });
  }

  jump() {
    this._sfxBlip({ f0: 360, f1: 520, dur: 0.17, vel: 0.075, type: 'sine' });
    this._sfxBlip({ f0: 540, f1: 720, dur: 0.12, vel: 0.03, type: 'triangle', delay: 0.01 });
  }

  doubleJump() {
    this._sfxBlip({ f0: 520, f1: 780, dur: 0.22, vel: 0.07, type: 'sine' });
    this._sfxBlip({ f0: 780, f1: 1040, dur: 0.3, vel: 0.04, type: 'sine', delay: 0.045 });
  }

  land(soft = false) {
    this._sfxBlip({ f0: soft ? 130 : 150, f1: 60, dur: 0.16, vel: soft ? 0.045 : 0.08, type: 'sine' });
    this._sfxNoise({ dur: 0.1, vel: soft ? 0.018 : 0.032, freq: 500, type: 'lowpass' });
  }

  bounce() {
    this._sfxBlip({ f0: 260, f1: 540, dur: 0.3, vel: 0.09, type: 'sine' });
    this._sfxBlip({ f0: 620, f1: 980, dur: 0.34, vel: 0.04, type: 'triangle', delay: 0.06 });
    this._sfxNoise({ dur: 0.12, vel: 0.02, freq: 380, type: 'lowpass' });
  }

  collect(streak = 0) {
    const scale = [0, 2, 4, 7, 9, 12, 14, 16];
    const notes = [76, 79, 81, 84, 86, 88, 91, 93];
    const midi = notes[Math.min(notes.length - 1, streak % 8)];
    void scale;
    this._bell(midi, this.ctx ? this.ctx.currentTime : 0, 0.055, 1.1);
    this._sfxBlip({ f0: mtof(midi + 12), f1: mtof(midi + 19), dur: 0.26, vel: 0.03, type: 'sine' });
  }

  checkpoint() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [0, 4, 7, 12].forEach((n, i) => {
      this._sfxBlip({ f0: mtof(67 + n), f1: mtof(67 + n), dur: 0.9, vel: 0.045, type: 'sine', delay: i * 0.09 });
    });
    void t;
  }

  gateOpen() {
    this._sfxBlip({ f0: 220, f1: 660, dur: 1.1, vel: 0.06, type: 'sine' });
    this._sfxBlip({ f0: 330, f1: 880, dur: 1.4, vel: 0.04, type: 'triangle', delay: 0.12 });
    this._bell(88, this.ctx ? this.ctx.currentTime + 0.3 : 0, 0.04, 2.4);
  }

  respawn() {
    this._sfxBlip({ f0: 420, f1: 200, dur: 0.45, vel: 0.04, type: 'sine' });
    this._sfxBlip({ f0: 280, f1: 140, dur: 0.5, vel: 0.03, type: 'sine', delay: 0.08 });
  }

  complete() {
    if (!this.ctx) return;
    const notes = [62, 66, 69, 74, 78, 81];
    notes.forEach((n, i) => {
      this._bell(n + 12, this.ctx.currentTime + i * 0.16, 0.045, 2.4);
      this._sfxBlip({ f0: mtof(n), f1: mtof(n), dur: 1.6, vel: 0.03, type: 'sine', delay: i * 0.16 });
    });
  }

  // ------------------------------------------------------------- ambience
  _ambientEvents(dt) {
    this._ensureAmbient();
    if (!this.ambientNodes) return;
    if (this.muted) return;

    this.birdTimer -= dt;
    if (this.birdTimer <= 0) {
      this.birdTimer = 5 + this.rng() * 11;
      if (this.ambience.birds > 0.05 && this.rng() < this.ambience.birds) this._chirp();
    }

    this.rainTimer -= dt;
    if (this.rainTimer <= 0) {
      this.rainTimer = 0.35 + this.rng() * 1.6;
      if (this.ambience.rain > 0.1) {
        this._sfxNoise({ dur: 0.05, vel: 0.006 * this.ambience.rain, freq: 3200 + this.rng() * 1400, type: 'highpass' });
      }
    }
  }

  _chirp() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + this.rng() * 0.2;
    const pn = ctx.createStereoPanner();
    pn.pan.value = (this.rng() - 0.5) * 1.2;
    pn.connect(this.ambientGain);
    const notes = 3 + Math.floor(this.rng() * 4);
    const base = 1900 + this.rng() * 900;
    for (let i = 0; i < notes; i++) {
      const o = ctx.createOscillator();
      o.type = 'sine';
      const st = t + i * (0.075 + this.rng() * 0.05);
      const f = base * (0.88 + this.rng() * 0.3) * (i % 2 ? 1.14 : 1);
      o.frequency.setValueAtTime(f, st);
      o.frequency.exponentialRampToValueAtTime(f * (1.15 + this.rng() * 0.1), st + 0.055);
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, st);
      g.gain.linearRampToValueAtTime(0.014, st + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, st + 0.08);
      o.connect(g);
      g.connect(pn);
      o.start(st);
      o.stop(st + 0.1);
    }
  }
}

import { LEVELS } from './levels.js';
import { Background } from './background.js';
import { FX } from './fx.js';
import {
  TAU, clamp, damp, lerp, rgba, roundedRect, ellipse,
  overlap, hash, mulberry32, smoothstep,
} from './util.js';

const FIXED = 1 / 120;
const PLAYER_W = 30;
const PLAYER_H = 42;

export class Game {
  constructor(canvas, audio, hooks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.audio = audio;
    this.hooks = hooks;
    this.fx = new FX();
    this.time = 0;
    this.lastTs = 0;
    this.accum = 0;
    this.mode = 'menu';
    this.input = { axis: 0, jumpHeld: false, jumpBuffer: 0 };
    this.prevJumpHeld = false;
    this.camera = { x: 0, y: 0 };
    this.levelIndex = 0;
    this.levelDef = LEVELS[0];
    this.level = LEVELS[0];
    this.player = null;
    this.ambient = [];
    this.decor = { grass: [], flowers: [], pebbles: [], vines: [] };
    this.fallTimer = 0;
    this.gateHint = 0;
    this.completeInfo = null;
    this.streak = 0;
    this.streakTimer = 0;
    this.fps = 60;
    this._fpsAcc = 0;
    this._fpsCount = 0;

    this.resize();
    this._onResize = () => this.resize();
    window.addEventListener('resize', this._onResize);

    this.attract(0);
    this._raf = requestAnimationFrame(this._frame);
  }

  resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.cssW = w;
    this.cssH = h;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    if (this.canvas.width !== Math.round(w * this.dpr) || this.canvas.height !== Math.round(h * this.dpr)) {
      this.canvas.width = Math.round(w * this.dpr);
      this.canvas.height = Math.round(h * this.dpr);
    }
    const landscape = w >= h;
    let z = landscape
      ? clamp(h / 720, 0.9, 1.4)
      : clamp(w / 480, 0.78, 1.15);
    z = Math.max(z, w / 1500, h / 1080);
    this.zoom = z;
    this.viewW = w / z;
    this.viewH = h / z;
    if (this.player) this.clampCamera();
  }

  // ------------------------------------------------------------------ setup
  attract(index = 0) {
    this.buildLevel(index, { restore: false });
    this.mode = 'menu';
    this.accum = 0;
    this.camera.x = clamp(420 - this.viewW / 2, 0, Math.max(0, this.level.width - this.viewW));
    this.camera.y = clamp(120, 0, Math.max(0, this.level.height - this.viewH));
    this.fx.list.length = 0;
  }

  buildLevel(index, options = {}) {
    const def = LEVELS[index];
    this.levelIndex = index;
    this.levelDef = def;
    this.level = def;
    this.background = new Background(def.theme, index * 3 + 2);
    this.audio.setMusic(def.theme.music, 1.6);
    this.audio.setAmbience(def.theme.ambient);

    this.solids = def.ground.map(([x, y, w, h = 470]) => ({ x, y, w, h }));
    this.platforms = def.platforms.map(([x, y, w]) => ({ x, y, w, h: 16, oneWay: true }));
    this.movers = (def.movers || []).map((m, i) => ({
      ...m, h: 18, baseX: m.x, baseY: m.y, phase: i * 1.9,
      prevX: m.x, prevY: m.y, dx: 0, dy: 0, oneWay: true,
    }));
    this.mushrooms = (def.mushrooms || []).map(([x, y], i) => ({
      x, y, bounce: 0, phase: i * 1.7,
    }));
    this.stars = def.stars.map(([x, y], i) => ({
      id: i, x, y, collected: false, phase: i * 0.83, bob: 0,
    }));
    this.checkpoints = (def.checkpoints || []).map(([x, y], i) => ({
      x, y, active: false, index: i, bloom: 0, phase: i * 1.3,
    }));
    this.gate = def.gate ? { ...def.gate, unlocked: false, open: 0, glow: 0 } : null;
    this.goal = { x: def.goal[0], y: def.goal[1], w: 108, h: 170, bloom: 0 };
    this.starsTotal = this.stars.length;
    this.collectedCount = 0;
    this.fallTimer = 0;
    this.completeInfo = null;
    this.streak = 0;
    this.streakTimer = 0;
    this.gateHint = 0;
    this.ambient = this.buildAmbient();
    this.buildDecor();

    const spawn = def.spawn;
    this.player = {
      x: spawn[0] - PLAYER_W / 2,
      y: spawn[1],
      w: PLAYER_W, h: PLAYER_H,
      vx: 0, vy: 0,
      facing: 1, onGround: false, moverRef: null,
      coyote: 0, jumpsUsed: 0,
      squash: 0, squashVel: 0, runPhase: 0,
      blink: 2.4, blinkTime: 0,
      tailX: spawn[0] - 40, tailY: spawn[1] + 12,
      idle: 0,
    };
    this.respawnPoint = { x: spawn[0], y: spawn[1] + PLAYER_H, checkpoint: -1 };

    if (options.restore) {
      if (options.collected) {
        for (const id of options.collected) {
          const s = this.stars[id];
          if (s) {
            s.collected = true;
            this.collectedCount++;
          }
        }
      }
      const cpIndex = typeof options.checkpoint === 'number' ? options.checkpoint : -1;
      if (cpIndex >= 0 && this.checkpoints[cpIndex]) {
        for (let i = 0; i <= cpIndex; i++) this.checkpoints[i].active = true;
        const cp = this.checkpoints[cpIndex];
        this.respawnPoint = { x: cp.x, y: cp.y, checkpoint: cpIndex };
        this.player.x = cp.x - PLAYER_W / 2;
        this.player.y = cp.y - PLAYER_H - 2;
      }
    }

    this.fx.list.length = 0;
    this.camera.x = clamp(this.player.x + PLAYER_W / 2 - this.viewW / 2, 0, Math.max(0, def.width - this.viewW));
    this.camera.y = clamp(this.player.y + PLAYER_H / 2 - this.viewH * 0.58, 0, Math.max(0, def.height - this.viewH));
    this.clampCamera();
  }

  buildAmbient() {
    const def = this.levelDef;
    const rng = mulberry32(this.levelIndex * 151 + 13);
    const list = [];
    const count = 52;
    for (let i = 0; i < count; i++) {
      list.push({
        kind: 'mote',
        x: rng() * def.width,
        y: 120 + rng() * 1000,
        size: 1.2 + rng() * 2.2,
        phase: rng() * TAU,
        speed: 0.4 + rng() * 0.9,
        drift: 6 + rng() * 16,
        vy: -2 + rng() * 5,
      });
    }
    const petalCount = 34;
    for (let i = 0; i < petalCount; i++) {
      list.push({
        kind: 'petal',
        x: rng() * def.width,
        y: 80 + rng() * 1100,
        size: 2.4 + rng() * 3.2,
        phase: rng() * TAU,
        rot: rng() * TAU,
        vr: (rng() - 0.5) * 1.8,
        vy: 10 + rng() * 22,
        vx: -16 + rng() * 32,
        color: rng() < 0.6 ? def.theme.flower : def.theme.flower2,
      });
    }
    return list;
  }

  buildDecor() {
    const th = this.levelDef.theme;
    const grass = [];
    const flowers = [];
    const pebbles = [];
    const vines = [];
    const surfaces = [
      ...this.solids.map((s) => ({ x: s.x, y: s.y, w: s.w, tall: true })),
      ...this.platforms.map((p) => ({ x: p.x, y: p.y, w: p.w, tall: false })),
    ];
    for (const s of surfaces) {
      for (let x = s.x + 10; x < s.x + s.w - 8; x += 22) {
        const r = hash(x * 0.37 + s.y * 0.11 + this.levelIndex * 7);
        if (r < 0.34) {
          grass.push({ x, y: s.y + 2, h: 5 + hash(x * 1.7) * 11, phase: hash(x * 3.1) * TAU });
        }
        if (r > 0.92) {
          flowers.push({
            x, y: s.y - 2, scale: 0.65 + hash(x * 2.3) * 0.6,
            color: r > 0.963 ? th.flower2 : th.flower,
            phase: hash(x * 4.4) * TAU,
          });
        }
      }
      if (s.tall) {
        for (let y = s.y + 70; y < Math.min(s.y + 430, this.levelDef.height); y += 90) {
          for (let k = 0; k < 2; k++) {
            const px = s.x + 30 + hash(s.x + y * 1.3 + k * 41) * (s.w - 60);
            pebbles.push({ x: px, y, r: 2 + hash(px) * 4 });
          }
        }
      } else {
        for (let k = 0; k < 2; k++) {
          const vx = s.x + 18 + hash(s.x + k * 17) * (s.w - 36);
          vines.push({ x: vx, y: s.y + 16, len: 16 + hash(vx * 1.9) * 46, phase: hash(vx) * TAU });
        }
      }
    }
    this.decor = { grass, flowers, pebbles, vines };
  }

  // ------------------------------------------------------------------ public
  startLevel(index, options = {}) {
    this.buildLevel(index, options);
    this.mode = 'play';
    this.accum = 0;
    this.input.jumpBuffer = 0;
    this.input.jumpHeld = false;
    this.prevJumpHeld = false;
    this.hooks.onLevelStart?.(index, this.levelDef);
    this.hooks.onHud?.(this.collectedCount, this.starsTotal, 0);
  }

  restartLevel() {
    this.startLevel(this.levelIndex, { restore: false });
  }

  pause() {
    if (this.mode !== 'play') return;
    this.mode = 'paused';
    this.input.axis = 0;
    this.input.jumpHeld = false;
  }

  resume() {
    if (this.mode !== 'paused') return;
    this.mode = 'play';
    this.accum = 0;
  }

  setAxis(axis) {
    this.input.axis = clamp(axis, -1, 1);
  }

  setJumpHeld(held) {
    this.input.jumpHeld = !!held;
  }

  queueJump() {
    this.input.jumpBuffer = 0.15;
  }

  debugState() {
    return {
      mode: this.mode,
      level: this.levelIndex,
      x: this.player?.x,
      y: this.player?.y,
      vx: this.player?.vx,
      vy: this.player?.vy,
      onGround: this.player?.onGround,
      collected: this.collectedCount,
      total: this.starsTotal,
      gate: this.gate ? { unlocked: this.gate.unlocked, need: this.gate.need } : null,
      fps: Math.round(this.fps),
    };
  }

  // ------------------------------------------------------------------ frame
  _frame = (ts) => {
    this._raf = requestAnimationFrame(this._frame);
    if (!this.lastTs) this.lastTs = ts;
    const raw = (ts - this.lastTs) / 1000;
    this.lastTs = ts;
    const dt = clamp(raw, 0, 0.05);
    this.time += dt;

    this._fpsAcc += raw;
    this._fpsCount++;
    if (this._fpsAcc > 0.5) {
      this.fps = this._fpsCount / this._fpsAcc;
      this._fpsAcc = 0;
      this._fpsCount = 0;
    }

    if (this.mode === 'play' && this.fallTimer <= 0) {
      this.accum += dt;
      let steps = 0;
      while (this.accum >= FIXED && steps < 10) {
        this._step(FIXED);
        this.accum -= FIXED;
        steps++;
      }
    }
    if (this.mode === 'paused' || this.mode === 'complete') {
      this.accum = 0;
    }

    if (this.mode !== 'play' || this.fallTimer > 0) {
      this._updateVisuals(dt);
    }
    this.fx.update(dt);
    this._updateAmbient(dt);
    this._updateCamera(dt);
    this.render();
    this.audio.update(dt);
  };

  _step(dt) {
    this.streakTimer = Math.max(0, this.streakTimer - dt);
    if (this.streakTimer <= 0 && this.streak > 0) this.streak = 0;
    this.gateHint = Math.max(0, this.gateHint - dt);
    this._updateMovers(dt);

    if (this.fallTimer > 0) {
      const before = this.fallTimer;
      this.fallTimer = Math.max(0, this.fallTimer - dt);
      if (before > 0.42 && this.fallTimer <= 0.42) this._relocate();
      return;
    }

    this._updatePlayer(dt);
    this._updateVisuals(dt);
    this._updateMushrooms(dt);
    this._updatePickups(dt);
  }

  _updateVisuals(dt) {
    const p = this.player;
    if (!p) return;
    p.idle += dt;
    p.blink -= dt;
    if (p.blink <= 0) {
      p.blinkTime = 0.13;
      p.blink = 2.4 + Math.random() * 3.5;
    }
    if (p.blinkTime > 0) p.blinkTime -= dt;

    if (p.onGround && Math.abs(p.vx) > 40) p.runPhase += Math.abs(p.vx) * dt * 0.052;
    else p.runPhase = damp(p.runPhase, 0, 6, dt);

    const cx = p.x + p.w / 2;
    const targetX = cx - p.facing * (30 + Math.min(28, Math.abs(p.vx) * 0.075));
    const targetY = p.y + 18 + Math.sin(this.time * 3.4) * 4 - p.vy * 0.018;
    p.tailX = damp(p.tailX ?? targetX, targetX, 7, dt);
    p.tailY = damp(p.tailY ?? targetY, targetY, 6, dt);
  }

  // ------------------------------------------------------------------ physics
  _updateMovers(dt) {
    for (const m of this.movers) {
      m.prevX = m.x;
      m.prevY = m.y;
      const ang = this.time * (m.speed / Math.max(1, m.range)) + m.phase;
      if (m.axis === 'x') m.x = m.baseX + Math.sin(ang) * m.range;
      else m.y = m.baseY + Math.sin(ang) * m.range;
      m.dx = m.x - m.prevX;
      m.dy = m.y - m.prevY;
    }
  }

  _updatePlayer(dt) {
    const p = this.player;
    const input = this.input;
    if (!p) return;

    input.jumpBuffer = Math.max(0, input.jumpBuffer - dt);

    // ride moving platforms
    if (p.onGround && p.moverRef) {
      p.x += p.moverRef.dx;
      p.y += p.moverRef.dy;
    }
    p.moverRef = null;

    const wasOnGround = p.onGround;
    const fallSpeed = p.vy;

    // Horizontal movement — soft acceleration, gentle friction.
    const accel = p.onGround ? 2500 : 1750;
    const maxSpeed = 292;
    if (input.axis !== 0) {
      p.vx += input.axis * accel * dt;
      if (Math.abs(p.vx) > maxSpeed) p.vx = clamp(p.vx, -maxSpeed, maxSpeed);
      p.facing = input.axis > 0 ? 1 : -1;
    } else {
      const friction = p.onGround ? 2500 : 320;
      if (Math.abs(p.vx) <= friction * dt) p.vx = 0;
      else p.vx -= Math.sign(p.vx) * friction * dt;
    }

    // jump cut
    if (this.prevJumpHeld && !input.jumpHeld && p.vy < -220) p.vy *= 0.56;
    this.prevJumpHeld = input.jumpHeld;

    // Gravity — floaty and forgiving.
    let gravity = 2020;
    if (p.vy < 0 && input.jumpHeld) gravity *= 0.82;
    p.vy = Math.min(1000, p.vy + gravity * dt);

    // Coyote time / jump charges.
    if (p.onGround) {
      p.coyote = 0.13;
      p.jumpsUsed = 0;
    } else {
      p.coyote = Math.max(0, p.coyote - dt);
    }

    if (input.jumpBuffer > 0 && !this.completeInfo) {
      if (p.onGround || p.coyote > 0) {
        this._jump(-730, false);
        input.jumpBuffer = 0;
      } else if (p.jumpsUsed < 2) {
        this._jump(-642, true);
        input.jumpBuffer = 0;
      }
    }

    p.onGround = false;

    // ---- X axis collisions
    p.x += p.vx * dt;
    const gateBox = this.gate && !this.gate.unlocked
      ? { x: this.gate.x, y: this.gate.y, w: this.gate.w, h: this.gate.h }
      : null;
    const solidsX = gateBox ? [...this.solids, gateBox] : this.solids;
    for (const s of solidsX) {
      if (!overlap(p, s)) continue;
      if (p.vx > 0) p.x = s.x - p.w;
      else if (p.vx < 0) p.x = s.x + s.w;
      p.vx = 0;
    }
    p.x = clamp(p.x, 0, this.level.width - p.w);

    // ---- Y axis collisions
    const prevBottom = p.y + p.h;
    p.y += p.vy * dt;
    let landed = false;

    for (const s of solidsX) {
      if (!overlap(p, s)) continue;
      if (p.vy > 0) {
        p.y = s.y - p.h;
        p.vy = 0;
        landed = true;
      } else if (p.vy < 0) {
        p.y = s.y + s.h;
        p.vy = 0;
      }
    }

    // one-way platforms and movers
    if (p.vy >= 0) {
      const candidates = [...this.platforms, ...this.movers];
      for (const pl of candidates) {
        const withinX = p.x + p.w > pl.x + 2 && p.x < pl.x + pl.w - 2;
        if (!withinX) continue;
        const top = pl.y;
        if (prevBottom <= top + 7 && p.y + p.h >= top) {
          p.y = top - p.h;
          p.vy = 0;
          landed = true;
          if (pl.dx !== undefined) p.moverRef = pl;
        }
      }
    }

    // safety: keep inside solid columns horizontally if embedded
    for (const s of this.solids) {
      if (overlap(p, s)) {
        const fromLeft = Math.abs(p.x + p.w - s.x);
        const fromRight = Math.abs(s.x + s.w - p.x);
        if (fromLeft < fromRight) p.x = s.x - p.w;
        else p.x = s.x + s.w;
        p.vx = 0;
      }
    }

    p.onGround = landed;
    if (p.onGround) {
      p.jumpsUsed = 0;
      p.coyote = 0.13;
    }

    if (!wasOnGround && p.onGround && fallSpeed > 220) {
      const power = clamp(fallSpeed / 2300, 0.12, 0.38);
      p.squash = power;
      p.squashVel = 0;
      this.audio.land(fallSpeed < 560);
      this.fx.burst(p.x + p.w / 2, p.y + p.h, {
        color: '#f4e4ca', count: 6, speed: 40, life: 0.5, size: 2.4, gravity: -18, additive: false, angle: 0, spread: Math.PI * 2,
      });
    }

    // squash / stretch spring
    p.squashVel += (-p.squash * 230 - p.squashVel * 16) * dt;
    p.squash += p.squashVel * dt;

    // footstep puffs
    if (p.onGround && Math.abs(p.vx) > 150) {
      this._stepDust = (this._stepDust || 0) + dt;
      if (this._stepDust > 0.16) {
        this._stepDust = 0;
        this.fx.spawn({
          x: p.x + p.w / 2 - p.facing * 8, y: p.y + p.h - 1,
          vx: -p.facing * 16, vy: -12, life: 0.45, maxLife: 0.45, size: 2.6,
          color: '#f6ead3', type: 'dust', additive: false, gravity: -6, drag: 0.94,
        });
      }
    }

    // mushroom bounce check
    for (const m of this.mushrooms) {
      const capTop = m.y - 62;
      const feet = p.y + p.h;
      if (
        p.vy > 90 &&
        feet >= capTop - 2 && feet <= capTop + 30 &&
        Math.abs(p.x + p.w / 2 - m.x) < 38
      ) {
        p.y = capTop - p.h;
        p.vy = -1040;
        p.jumpsUsed = 0;
        p.coyote = 0;
        p.squash = -0.28;
        p.squashVel = -1.4;
        m.bounce = 1;
        this.audio.bounce();
        this.fx.ring(m.x, m.y - 62, '#ffe6bc', 16, 0.6);
        this.fx.burst(m.x, m.y - 60, {
          color: this.levelDef.theme.flower, count: 12, speed: 130, life: 0.8,
          size: 3.2, gravity: 220, type: 'petal', additive: false, angle: -Math.PI / 2, spread: Math.PI,
        });
      }
    }

    // fell off the world — no penalty, just a soft return.
    if (p.y > this.level.height + 110) {
      this.fallTimer = 1.0;
      this.audio.respawn();
    }
  }

  _jump(vy, isDouble) {
    const p = this.player;
    p.vy = vy;
    p.onGround = false;
    p.moverRef = null;
    p.coyote = 0;
    p.jumpsUsed = isDouble ? 2 : 1;
    p.squash = -0.2;
    p.squashVel = 0.6;
    if (isDouble) {
      this.audio.doubleJump();
      this.fx.ring(p.x + p.w / 2, p.y + p.h - 6, '#cfe6d2', 12, 0.55);
      this.fx.burst(p.x + p.w / 2, p.y + p.h - 4, {
        color: '#fff0c4', count: 9, speed: 80, life: 0.6, size: 2.6, gravity: -30, type: 'dot',
      });
    } else {
      this.audio.jump();
      this.fx.burst(p.x + p.w / 2, p.y + p.h, {
        color: '#f2e6d2', count: 5, speed: 40, life: 0.4, size: 2.3,
        gravity: -20, additive: false, angle: 0, spread: Math.PI * 2,
      });
    }
  }

  _updateMushrooms(dt) {
    for (const m of this.mushrooms) {
      m.bounce = Math.max(0, m.bounce - dt * 2.6);
    }
  }

  _updatePickups(dt) {
    const p = this.player;
    const cx = p.x + p.w / 2;
    const cy = p.y + p.h / 2;

    for (const s of this.stars) {
      if (s.collected) continue;
      s.bob = Math.sin(this.time * 1.8 + s.phase) * 5;
      const dx = cx - s.x;
      const dy = cy - (s.y + s.bob);
      if (dx * dx + dy * dy < 42 * 42) {
        s.collected = true;
        this.collectedCount++;
        this.streak++;
        this.streakTimer = 2.6;
        this.fx.burst(s.x, s.y + s.bob, {
          color: '#ffe7a0', count: 12, speed: 85, life: 0.9, size: 3, gravity: -20, type: 'dot',
        });
        this.fx.ring(s.x, s.y + s.bob, '#ffeec0', 10, 0.6);
        this.fx.spawn({
          x: s.x, y: s.y, type: 'sparkle', color: '#fff6cf',
          size: 4, life: 0.8, maxLife: 0.8, vy: -40, gravity: -20, additive: true,
        });
        this.audio.collect(this.streak - 1);
        this.hooks.onCollect?.(this.levelIndex, s.id, this.collectedCount, this.starsTotal);
        if (this.gate && !this.gate.unlocked && this.collectedCount >= this.gate.need) {
          this._openGate();
        }
      }
    }

    // checkpoints
    for (const cp of this.checkpoints) {
      if (cp.active) {
        cp.bloom = Math.min(1, cp.bloom + dt * 2);
        continue;
      }
      const nearX = Math.abs(cx - cp.x) < 46;
      const nearY = p.y + p.h > cp.y - 100 && p.y + p.h < cp.y + 40;
      if (nearX && nearY) {
        cp.active = true;
        this.respawnPoint = { x: cp.x, y: cp.y, checkpoint: cp.index };
        this.audio.checkpoint();
        this.fx.ring(cp.x, cp.y - 66, '#ffe8b5', 14, 0.9);
        this.fx.burst(cp.x, cp.y - 62, {
          color: '#ffe6a8', count: 16, speed: 90, life: 1.2, size: 3, gravity: -30,
        });
        this.hooks.onCheckpoint?.(this.levelIndex, cp.index);
        this.hooks.onToast?.('a warm little light to return to');
      }
    }

    // gate hint
    if (this.gate && !this.gate.unlocked) {
      if (this.gate.open > 0) this.gate.open = 0;
      if (Math.abs(cx - (this.gate.x + this.gate.w / 2)) < 150 && this.gateHint <= 0) {
        const need = this.gate.need - this.collectedCount;
        this.hooks.onToast?.(`the bloom still needs ${need} more firefl${need === 1 ? 'y' : 'ies'}`);
        this.gateHint = 5.5;
      }
    } else if (this.gate) {
      this.gate.open = Math.min(1, this.gate.open + dt * 0.9);
      this.gate.glow = Math.min(1, this.gate.glow + dt);
    }

    // goal
    if (!this.completeInfo) {
      const goalRect = { x: this.goal.x - 54, y: this.goal.y - 150, w: 108, h: 150 };
      if (overlap(p, goalRect)) this._finishLevel();
    }
  }

  _openGate() {
    if (!this.gate || this.gate.unlocked) return;
    this.gate.unlocked = true;
    this.gate.glow = 0;
    this.audio.gateOpen();
    this.fx.ring(this.gate.x + this.gate.w / 2, this.gate.y + 40, '#ffe9ae', 22, 1.1);
    this.fx.burst(this.gate.x + this.gate.w / 2, this.gate.y + 40, {
      color: '#ffe6b0', count: 30, speed: 130, life: 1.4, size: 3.2, gravity: -40,
    });
    this.hooks.onGate?.(this.levelIndex);
    this.hooks.onToast?.('the bloom awakens');
  }

  _finishLevel() {
    const p = this.player;
    const info = {
      levelIndex: this.levelIndex,
      collected: this.collectedCount,
      total: this.starsTotal,
      isLast: this.levelIndex === LEVELS.length - 1,
    };
    this.mode = 'complete';
    this.completeInfo = info;
    this.goal.bloom = 1;
    p.vx = 0;
    p.vy = 0;
    p.onGround = true;
    this.audio.complete();
    this.fx.ring(this.goal.x, this.goal.y - 92, '#ffe9b4', 30, 1.4);
    this.fx.burst(this.goal.x, this.goal.y - 100, {
      color: '#ffe7ad', count: 26, speed: 130, life: 1.6, size: 3.4, gravity: -20,
    });
    this.fx.burst(this.goal.x, this.goal.y - 70, {
      color: this.levelDef.theme.flower, count: 22, speed: 110, life: 2.4,
      size: 3.6, gravity: 20, type: 'petal', additive: false, angle: -Math.PI / 2, spread: Math.PI * 1.4,
    });
    this.hooks.onComplete?.(info);
  }

  _relocate() {
    const p = this.player;
    const rp = this.respawnPoint;
    p.x = rp.x - p.w / 2;
    p.y = rp.y - p.h - 2;
    p.vx = 0;
    p.vy = 0;
    p.onGround = true;
    p.jumpsUsed = 0;
    p.moverRef = null;
    p.tailX = p.x + 10;
    p.tailY = p.y + 16;
    this.camera.x = clamp(p.x + p.w / 2 - this.viewW / 2, 0, Math.max(0, this.level.width - this.viewW));
    this.camera.y = clamp(p.y + p.h / 2 - this.viewH * 0.58, 0, Math.max(0, this.level.height - this.viewH));
    this.fx.burst(rp.x, rp.y - 6, {
      color: '#fff0c6', count: 18, speed: 70, life: 1.1, size: 3, gravity: -56,
      type: 'petal', additive: false, angle: -Math.PI / 2, spread: Math.PI * 1.4,
    });
    this.fx.ring(rp.x, rp.y - 12, '#ffe7ae', 14, 0.9);
  }

  _updateAmbient(dt) {
    const camL = this.camera.x - 260;
    const camR = this.camera.x + this.viewW + 260;
    for (const a of this.ambient) {
      if (a.kind === 'mote') {
        a.x += Math.sin(this.time * a.speed + a.phase) * a.drift * dt;
        a.y += a.vy * dt;
        if (a.y < 40) a.y = this.level.height - 80;
        a.y += Math.sin(this.time * 0.6 + a.phase) * 3 * dt;
      } else {
        a.x += (a.vx + Math.sin(this.time * 0.8 + a.phase) * 14) * dt;
        a.y += a.vy * dt;
        a.rot += a.vr * dt;
        if (a.y > this.level.height + 30 || a.x < camL - 400 || a.x > camR + 400) {
          a.x = camL + Math.random() * (camR - camL);
          a.y = -20;
        }
      }
      if (a.x < -100) a.x = this.level.width + 80;
      if (a.x > this.level.width + 100) a.x = -60;
    }
  }

  _updateCamera(dt) {
    if (!this.player) return;
    if (this.mode === 'menu') {
      const target = 620 + Math.sin(this.time * 0.032) * 380;
      const tx = clamp(target - this.viewW / 2, 0, Math.max(0, this.level.width - this.viewW));
      const ty = clamp(90 + Math.sin(this.time * 0.021) * 40, 0, Math.max(0, this.level.height - this.viewH));
      this.camera.x = damp(this.camera.x, tx, 0.55, dt);
      this.camera.y = damp(this.camera.y, ty, 0.5, dt);
      return;
    }
    const p = this.player;
    const lead = clamp(p.vx * 0.22, -90, 90);
    const tx = clamp(p.x + p.w / 2 + lead - this.viewW / 2, 0, Math.max(0, this.level.width - this.viewW));
    const ty = clamp(p.y + p.h / 2 - this.viewH * 0.56, 0, Math.max(0, this.level.height - this.viewH));
    this.camera.x = damp(this.camera.x, tx, 7.5, dt);
    this.camera.y = damp(this.camera.y, ty, 5.5, dt);
  }

  clampCamera() {
    if (!this.level) return;
    this.camera.x = clamp(this.camera.x, 0, Math.max(0, this.level.width - this.viewW));
    this.camera.y = clamp(this.camera.y, 0, Math.max(0, this.level.height - this.viewH));
  }

  // ------------------------------------------------------------------ render
  render() {
    const ctx = this.ctx;
    const { cssW: w, cssH: h, dpr, zoom, camera } = this;
    if (!this.background) return;

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.background.draw(ctx, camera, w, h, this.time, zoom);

    ctx.setTransform(dpr * zoom, 0, 0, dpr * zoom, 0, 0);
    ctx.translate(-camera.x, -camera.y);

    const view = { x: camera.x - 120, y: camera.y - 200, w: this.viewW + 240, h: this.viewH + 400 };
    this._drawWorld(ctx, view);

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this._drawWeather(ctx, w, h);
    this._drawVignette(ctx, w, h);
    this._drawRespawnFade(ctx, w, h);

    if (this.mode === 'menu') this._drawMenuSparkles(ctx, w, h);
  }

  _drawWorld(ctx, view) {
    const th = this.levelDef.theme;
    this._drawPlatforms(ctx, view, th);
    this._drawVines(ctx, view, th);
    for (const m of this.mushrooms) {
      if (m.x < view.x - 100 || m.x > view.x + view.w + 100) continue;
      this._drawMushroom(ctx, m, th);
    }
    for (const cp of this.checkpoints) {
      if (cp.x < view.x - 100 || cp.x > view.x + view.w + 100) continue;
      this._drawCheckpoint(ctx, cp, th);
    }
    if (this.gate) this._drawGate(ctx, th);
    this._drawGoal(ctx, th);
    this._drawStars(ctx, view);
    this._drawAmbient(ctx, view);
    this.fx.draw(ctx);
    this._drawPlayer(ctx, th);
  }

  _drawPlatforms(ctx, view, th) {
    for (const s of this.solids) {
      if (s.x + s.w < view.x - 60 || s.x > view.x + view.w + 60) continue;
      this._drawSolid(ctx, s, th);
    }
    for (const pl of this.platforms) {
      if (pl.x + pl.w < view.x - 80 || pl.x > view.x + view.w + 80) continue;
      this._drawFloat(ctx, pl, th);
    }
    for (const m of this.movers) {
      if (m.x + m.w < view.x - 80 || m.x > view.x + view.w + 80) continue;
      this._drawMover(ctx, m, th);
    }
    // grass blades + flowers + pebbles
    for (const g of this.decor.grass) {
      if (g.x < view.x - 30 || g.x > view.x + view.w + 30) continue;
      const sway = Math.sin(this.time * 1.3 + g.phase) * 2.4;
      ctx.strokeStyle = th.grassDark;
      ctx.lineWidth = 1.5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(g.x, g.y);
      ctx.quadraticCurveTo(g.x + sway * 0.4, g.y - g.h * 0.6, g.x + sway, g.y - g.h);
      ctx.stroke();
      if (g.h > 12) {
        ctx.beginPath();
        ctx.moveTo(g.x + 3, g.y);
        ctx.quadraticCurveTo(g.x + 3 + sway * 0.5, g.y - g.h * 0.45, g.x + 3 + sway * 0.8, g.y - g.h * 0.75);
        ctx.stroke();
      }
    }
    for (const f of this.decor.flowers) {
      if (f.x < view.x - 30 || f.x > view.x + view.w + 30) continue;
      this._drawFlower(ctx, f);
    }
    for (const p of this.decor.pebbles) {
      if (p.x < view.x - 20 || p.x > view.x + view.w + 20) continue;
      ctx.fillStyle = rgba(th.soilDark, 0.4);
      ellipse(ctx, p.x, p.y, p.r, p.r * 0.62);
      ctx.fill();
    }
  }

  _drawSolid(ctx, s, th) {
    const grad = ctx.createLinearGradient(0, s.y, 0, s.y + Math.min(420, s.h));
    grad.addColorStop(0, th.soilLight);
    grad.addColorStop(0.16, th.soil);
    grad.addColorStop(1, th.soilDark);
    ctx.fillStyle = grad;
    roundedRect(ctx, s.x, s.y, s.w, s.h, [22, 22, 0, 0]);
    ctx.fill();

    // grass cap
    const gg = ctx.createLinearGradient(0, s.y - 2, 0, s.y + 24);
    gg.addColorStop(0, th.grassLight);
    gg.addColorStop(0.45, th.grass);
    gg.addColorStop(1, th.grassDark);
    ctx.fillStyle = gg;
    roundedRect(ctx, s.x, s.y - 2, s.w, 24, [22, 22, 8, 8]);
    ctx.fill();

    ctx.fillStyle = rgba('#ffffff', 0.18);
    ctx.beginPath();
    ctx.ellipse(s.x + s.w / 2, s.y + 4, s.w / 2 - 18, 4, 0, 0, TAU);
    ctx.fill();

    // faint roots / texture
    ctx.strokeStyle = rgba(th.soilDark, 0.35);
    ctx.lineWidth = 1.2;
    const startX = Math.max(s.x + 30, Math.ceil((s.x + 30) / 90) * 90);
    for (let x = startX; x < s.x + s.w - 30; x += 90) {
      const hh = hash(x * 0.7) * 50 + 20;
      ctx.beginPath();
      ctx.moveTo(x, s.y + 34);
      ctx.quadraticCurveTo(x + 6, s.y + 34 + hh * 0.5, x - 3, s.y + 34 + hh);
      ctx.stroke();
    }
  }

  _drawFloat(ctx, pl, th) {
    const shadow = ctx.createLinearGradient(0, pl.y - 4, 0, pl.y + 22);
    shadow.addColorStop(0, th.grass);
    shadow.addColorStop(0.38, th.soilLight);
    shadow.addColorStop(1, th.soilDark);
    ctx.fillStyle = shadow;
    roundedRect(ctx, pl.x, pl.y - 2, pl.w, 22, 11);
    ctx.fill();

    const gg = ctx.createLinearGradient(0, pl.y - 4, 0, pl.y + 7);
    gg.addColorStop(0, th.grassLight);
    gg.addColorStop(1, th.grassDark);
    ctx.fillStyle = gg;
    roundedRect(ctx, pl.x, pl.y - 4, pl.w, 12, [9, 9, 4, 4]);
    ctx.fill();
  }

  _drawMover(ctx, m, th) {
    // soft glow beneath
    const g = ctx.createRadialGradient(m.x + m.w / 2, m.y + 16, 2, m.x + m.w / 2, m.y + 16, m.w * 0.8);
    g.addColorStop(0, rgba(th.accent, 0.22));
    g.addColorStop(1, rgba(th.accent, 0));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(m.x + m.w / 2, m.y + 14, m.w * 0.8, 0, TAU);
    ctx.fill();

    const body = ctx.createLinearGradient(0, m.y - 6, 0, m.y + 22);
    body.addColorStop(0, th.grassLight);
    body.addColorStop(0.4, th.grass);
    body.addColorStop(1, th.soilDark);
    ctx.fillStyle = body;
    roundedRect(ctx, m.x, m.y - 5, m.w, 24, 12);
    ctx.fill();
    ctx.fillStyle = rgba('#ffffff', 0.22);
    roundedRect(ctx, m.x + 10, m.y - 2, m.w - 20, 4, 2);
    ctx.fill();

    // little leaf fins
    ctx.fillStyle = rgba(th.grass, 0.9);
    for (const side of [-1, 1]) {
      const x = side < 0 ? m.x + 4 : m.x + m.w - 4;
      ctx.beginPath();
      ctx.ellipse(x + side * 4, m.y + 4, 12, 5, side * 0.5, 0, TAU);
      ctx.fill();
    }

    // hanging sparkle
    ctx.fillStyle = rgba(th.star, 0.9);
    ctx.beginPath();
    ctx.arc(m.x + m.w / 2, m.y + 16 + Math.sin(this.time * 2 + m.phase) * 2, 1.8, 0, TAU);
    ctx.fill();
  }

  _drawVines(ctx, view, th) {
    for (const v of this.decor.vines) {
      if (v.x < view.x - 20 || v.x > view.x + view.w + 20) continue;
      const sway = Math.sin(this.time * 0.9 + v.phase) * 5;
      ctx.strokeStyle = rgba(th.grassDark, 0.85);
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(v.x, v.y);
      ctx.quadraticCurveTo(v.x + sway * 0.3, v.y + v.len * 0.6, v.x + sway, v.y + v.len);
      ctx.stroke();
      ctx.fillStyle = rgba(th.grassDark, 0.8);
      const ly = v.y + v.len * 0.7;
      ctx.beginPath();
      ctx.ellipse(v.x + sway * 0.45 + 4, ly, 4, 2.2, 0.5, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(v.x + sway * 0.8 - 3, ly + 9, 3.4, 2, -0.4, 0, TAU);
      ctx.fill();
    }
  }

  _drawFlower(ctx, f) {
    const sway = Math.sin(this.time * 1.1 + f.phase) * 2;
    const baseY = f.y;
    const topY = f.y - 10 * f.scale;
    ctx.strokeStyle = rgba('#7fa083', 0.8);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(f.x, baseY);
    ctx.quadraticCurveTo(f.x + sway * 0.4, baseY - 6, f.x + sway, topY);
    ctx.stroke();
    ctx.fillStyle = f.color;
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU + 0.4;
      ctx.beginPath();
      ctx.ellipse(
        f.x + sway + Math.cos(a) * 2.6 * f.scale,
        topY + Math.sin(a) * 2.2 * f.scale,
        2.6 * f.scale, 1.7 * f.scale, a, 0, TAU,
      );
      ctx.fill();
    }
    ctx.fillStyle = '#f5d58d';
    ctx.beginPath();
    ctx.arc(f.x + sway, topY, 1.4 * f.scale, 0, TAU);
    ctx.fill();
  }

  _drawMushroom(ctx, m, th) {
    const squash = m.bounce;
    const sx = 1 + squash * 0.22;
    const sy = 1 - squash * 0.26;
    ctx.save();
    ctx.translate(m.x, m.y);
    ctx.scale(sx, sy);

    ctx.fillStyle = '#f1e4cf';
    roundedRect(ctx, -8, -30, 16, 30, [7, 7, 3, 3]);
    ctx.fill();
    ctx.fillStyle = rgba('#d8c3a6', 0.7);
    roundedRect(ctx, -8, -16, 16, 16, [0, 0, 3, 3]);
    ctx.fill();

    const capY = -42;
    const cg = ctx.createLinearGradient(0, capY - 24, 0, capY + 12);
    cg.addColorStop(0, '#f6c7c1');
    cg.addColorStop(0.6, th.accent);
    cg.addColorStop(1, '#c97f7f');
    ctx.fillStyle = cg;
    ctx.beginPath();
    ctx.ellipse(0, capY, 36, 20, 0, Math.PI, TAU);
    ctx.lineTo(36, capY + 2);
    ctx.quadraticCurveTo(0, capY + 16, -36, capY + 2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = rgba('#fff4e4', 0.88);
    const spots = [[-16, -52, 5], [5, -56, 4], [20, -48, 3.4], [-4, -45, 2.6]];
    for (const [sx2, sy2, r] of spots) {
      ctx.beginPath();
      ctx.ellipse(sx2, sy2, r * 1.15, r * 0.8, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // glow when freshly bounced
    if (m.bounce > 0.03) {
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(m.x, m.y - 44, 0, m.x, m.y - 44, 60);
      g.addColorStop(0, rgba('#ffe9b4', m.bounce * 0.35));
      g.addColorStop(1, rgba('#ffe9b4', 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(m.x, m.y - 44, 60, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }
  }

  _drawCheckpoint(ctx, cp, th) {
    const active = cp.active;
    const bob = Math.sin(this.time * 1.4 + cp.phase) * 2.5;
    const lx = cp.x;
    const ly = cp.y - 78 + bob;

    // pole
    ctx.strokeStyle = rgba('#7c6559', 0.8);
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cp.x, cp.y);
    ctx.quadraticCurveTo(cp.x - 4, cp.y - 40, cp.x - 16, cp.y - 64);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cp.x - 16, cp.y - 64);
    ctx.lineTo(lx, cp.y - 70);
    ctx.stroke();

    // glow
    if (active) {
      ctx.globalCompositeOperation = 'lighter';
      const pulse = 0.6 + Math.sin(this.time * 2 + cp.phase) * 0.15;
      const g = ctx.createRadialGradient(lx, ly, 2, lx, ly, 56);
      g.addColorStop(0, rgba('#ffe8ac', 0.5 * pulse));
      g.addColorStop(0.4, rgba('#ffd98c', 0.16));
      g.addColorStop(1, rgba('#ffd98c', 0));
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(lx, ly, 56, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    }

    // lantern glass
    const glass = ctx.createLinearGradient(lx, ly - 13, lx, ly + 13);
    if (active) {
      glass.addColorStop(0, '#fff4cf');
      glass.addColorStop(0.6, '#ffdf9d');
      glass.addColorStop(1, '#f2b775');
    } else {
      glass.addColorStop(0, 'rgba(255,248,235,0.75)');
      glass.addColorStop(1, 'rgba(206,196,196,0.5)');
    }
    ctx.fillStyle = glass;
    roundedRect(ctx, lx - 9, ly - 12, 18, 24, 8);
    ctx.fill();
    ctx.strokeStyle = rgba('#8d7568', 0.5);
    ctx.lineWidth = 1.4;
    roundedRect(ctx, lx - 9, ly - 12, 18, 24, 8);
    ctx.stroke();
    ctx.fillStyle = active ? '#e8b56f' : '#bcb2ad';
    roundedRect(ctx, lx - 11, ly - 15, 22, 4, 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(lx, ly - 16, 2.2, 0, TAU);
    ctx.fill();
    if (active) {
      ctx.fillStyle = '#fff8d9';
      ctx.beginPath();
      ctx.arc(lx, ly + 1, 4.5, 0, TAU);
      ctx.fill();
    }

    // base stones
    ctx.fillStyle = rgba(th.soilDark, 0.55);
    ctx.beginPath();
    ctx.ellipse(cp.x, cp.y + 1, 14, 4, 0, 0, TAU);
    ctx.fill();
  }

  _drawGate(ctx, th) {
    const gate = this.gate;
    if (!gate) return;
    const open = gate.open;
    const cx = gate.x + gate.w / 2;
    const baseY = gate.y + gate.h;
    const topY = gate.y;

    if (!gate.unlocked) {
      // leafy vine wall
      ctx.save();
      ctx.strokeStyle = rgba('#6e9277', 0.9);
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      for (let i = 0; i < 5; i++) {
        const x = gate.x + 8 + (i / 4) * (gate.w - 16);
        ctx.beginPath();
        ctx.moveTo(x, baseY);
        ctx.bezierCurveTo(x + 12, baseY - gate.h * 0.35, x - 14, baseY - gate.h * 0.7, x + 5, topY);
        ctx.stroke();
      }
      ctx.fillStyle = rgba(th.grass, 0.85);
      for (let i = 0; i < 26; i++) {
        const yy = baseY - 12 - hash(i * 3.7) * (gate.h - 20);
        const xx = gate.x + 4 + hash(i * 2.1) * (gate.w - 8);
        ctx.beginPath();
        ctx.ellipse(xx, yy, 8, 4.2, hash(i) * TAU, 0, TAU);
        ctx.fill();
      }
      ctx.restore();

      // closed bloom
      const by = topY + 28;
      this._drawBloom(ctx, cx, by, 1 + Math.sin(this.time * 1.2) * 0.04, th, 0.75, true);

      // requirement dots
      const need = gate.need;
      const have = Math.min(need, this.collectedCount);
      const dotW = 11;
      const totalW = need * dotW;
      const startX = cx - totalW / 2;
      for (let i = 0; i < need; i++) {
        const filled = i < have;
        ctx.fillStyle = filled ? rgba('#ffe7a0', 0.95) : rgba('#efe2d2', 0.42);
        ctx.beginPath();
        ctx.arc(startX + i * dotW + dotW / 2, gate.y - 22, 2.7, 0, TAU);
        ctx.fill();
        if (filled) {
          ctx.fillStyle = rgba('#ffe7a0', 0.2);
          ctx.beginPath();
          ctx.arc(startX + i * dotW + dotW / 2, gate.y - 22, 6, 0, TAU);
          ctx.fill();
        }
      }
    } else {
      // opening bloom and retreating vines
      const left = 1 - open;
      if (left > 0.02) {
        ctx.save();
        ctx.globalAlpha = left;
        ctx.strokeStyle = rgba('#8fb08f', 0.75);
        ctx.lineWidth = 4;
        for (let i = 0; i < 5; i++) {
          const x = gate.x + 8 + (i / 4) * (gate.w - 16);
          ctx.beginPath();
          ctx.moveTo(x, baseY - (1 - left) * gate.h);
          ctx.quadraticCurveTo(x + 8, baseY - gate.h * 0.6, x - 2, topY);
          ctx.stroke();
        }
        ctx.restore();
      }
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createLinearGradient(cx, baseY, cx, topY - 40);
      g.addColorStop(0, rgba('#ffe7ae', 0.1 + gate.glow * 0.14));
      g.addColorStop(0.6, rgba('#ffe7ae', 0.18 * gate.glow));
      g.addColorStop(1, rgba('#ffe7ae', 0));
      ctx.fillStyle = g;
      ctx.fillRect(gate.x - 30, topY - 40, gate.w + 60, gate.h + 40);
      ctx.globalCompositeOperation = 'source-over';
      this._drawBloom(ctx, cx, topY + 28, 0.9 + open * 0.25, th, 0.9, false);
    }
  }

  _drawBloom(ctx, x, y, scale, th, alpha, closed) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.globalAlpha = alpha;
    const petalCount = 6;
    for (let i = 0; i < petalCount; i++) {
      const a = (i / petalCount) * TAU + this.time * 0.05;
      const spread = closed ? 0.55 : 1;
      ctx.save();
      ctx.rotate(a);
      const grad = ctx.createLinearGradient(0, -8, 0, -34);
      grad.addColorStop(0, '#ffeccd');
      grad.addColorStop(1, closed ? '#eab6b1' : '#ffd8c4');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.ellipse(0, -22 * spread, 8, 18 * spread, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.fillStyle = '#ffe5a2';
    ctx.beginPath();
    ctx.arc(0, 0, closed ? 6 : 8, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  _drawGoal(ctx, th) {
    const goal = this.goal;
    const x = goal.x;
    const base = goal.y;
    const top = base - 132;
    const done = this.completeInfo ? 1 : 0;
    const pulse = 0.7 + Math.sin(this.time * 1.6) * 0.15 + done * 0.3;

    // light column
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createLinearGradient(x, base, x, top - 70);
    g.addColorStop(0, rgba('#ffe7ad', 0.2 * pulse));
    g.addColorStop(0.55, rgba('#ffe7ad', 0.13 * pulse));
    g.addColorStop(1, rgba('#ffe7ad', 0));
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x - 60, base);
    ctx.quadraticCurveTo(x - 38, top - 30, x - 26, top);
    ctx.lineTo(x + 26, top);
    ctx.quadraticCurveTo(x + 38, top - 30, x + 60, base);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // arch vines
    ctx.strokeStyle = rgba('#7e9c80', 0.9);
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(x + side * 48, base);
      ctx.bezierCurveTo(x + side * 54, base - 60, x + side * 38, top + 30, x + side * 6, top - 2);
      ctx.stroke();
    }
    ctx.fillStyle = rgba(th.grass, 0.9);
    for (let i = 0; i < 16; i++) {
      const side = i % 2 ? 1 : -1;
      const yy = base - 12 - (i / 16) * 110;
      const xx = x + side * (46 - (i / 16) * 42);
      ctx.beginPath();
      ctx.ellipse(xx, yy, 7, 3.6, side * 0.6, 0, TAU);
      ctx.fill();
    }

    this._drawBloom(ctx, x, top - 8, done ? 1.25 : 1 + Math.sin(this.time * 1.2) * 0.04, th, done ? 1 : 0.92, false);

    // drifting glow dots
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 7; i++) {
      const t = (this.time * 0.35 + i / 7) % 1;
      const yy = base - t * 140;
      const xx = x + Math.sin(t * 7 + i * 2) * 26;
      ctx.fillStyle = rgba('#ffe7ad', 0.45 * (1 - t));
      ctx.beginPath();
      ctx.arc(xx, yy, 2, 0, TAU);
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
  }

  _drawStars(ctx, view) {
    for (const s of this.stars) {
      if (s.collected) continue;
      if (s.x < view.x - 60 || s.x > view.x + view.w + 60) continue;
      const y = s.y + Math.sin(this.time * 1.8 + s.phase) * 5;
      const pulse = 0.75 + Math.sin(this.time * 2.6 + s.phase * 1.7) * 0.25;

      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const glow = ctx.createRadialGradient(s.x, y, 0, s.x, y, 34 * pulse);
      glow.addColorStop(0, rgba('#fff4cf', 0.8));
      glow.addColorStop(0.28, rgba('#ffe39a', 0.45));
      glow.addColorStop(1, rgba('#ffe39a', 0));
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(s.x, y, 34 * pulse, 0, TAU);
      ctx.fill();
      ctx.restore();

      // wings
      const flap = Math.sin(this.time * 9 + s.phase) * 0.5;
      ctx.save();
      ctx.translate(s.x, y);
      ctx.fillStyle = 'rgba(255, 253, 238, 0.55)';
      ctx.beginPath();
      ctx.ellipse(-5, -2, 7, 3.2, -0.55 - flap, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(5, -2, 7, 3.2, 0.55 + flap, 0, TAU);
      ctx.fill();

      const core = ctx.createRadialGradient(-1.5, -2, 0.5, 0, 0, 7.5);
      core.addColorStop(0, '#fffdf0');
      core.addColorStop(0.5, '#ffe8a4');
      core.addColorStop(1, '#f4c670');
      ctx.fillStyle = core;
      ctx.beginPath();
      ctx.arc(0, 0, 7, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255, 250, 237, 0.95)';
      ctx.beginPath();
      ctx.arc(-2, -2.5, 2.2, 0, TAU);
      ctx.fill();
      ctx.restore();

      // tiny sparkle cross
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = rgba('#fff7d9', 0.6);
      ctx.lineWidth = 1;
      const ss = 12 + pulse * 4;
      ctx.beginPath();
      ctx.moveTo(s.x - ss, y);
      ctx.lineTo(s.x + ss, y);
      ctx.moveTo(s.x, y - ss);
      ctx.lineTo(s.x, y + ss);
      ctx.stroke();
      ctx.restore();
    }
  }

  _drawAmbient(ctx, view) {
    ctx.save();
    for (const a of this.ambient) {
      if (a.x < view.x - 50 || a.x > view.x + view.w + 50) continue;
      if (a.kind === 'mote') {
        ctx.globalCompositeOperation = 'lighter';
        const pulse = 0.45 + 0.35 * Math.sin(this.time * 1.4 + a.phase);
        const r = a.size * 4.5;
        const g = ctx.createRadialGradient(a.x, a.y, 0, a.x, a.y, r);
        g.addColorStop(0, rgba('#fff6d8', 0.8 * pulse));
        g.addColorStop(0.3, rgba('#ffe39c', 0.35 * pulse));
        g.addColorStop(1, rgba('#ffe39c', 0));
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(a.x, a.y, r, 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      } else {
        ctx.save();
        ctx.translate(a.x, a.y);
        ctx.rotate(a.rot);
        ctx.globalAlpha = 0.62;
        ctx.fillStyle = a.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, a.size, a.size * 0.52, 0, 0, TAU);
        ctx.fill();
        ctx.restore();
      }
    }
    ctx.restore();
  }

  _findGroundBelow(cx, feet) {
    let best = Infinity;
    for (const s of this.solids) {
      if (cx > s.x && cx < s.x + s.w && s.y >= feet - 4 && s.y < best) best = s.y;
    }
    for (const pl of this.platforms) {
      if (cx > pl.x && cx < pl.x + pl.w && pl.y >= feet - 4 && pl.y < best) best = pl.y;
    }
    for (const m of this.movers) {
      if (cx > m.x && cx < m.x + m.w && m.y >= feet - 4 && m.y < best) best = m.y;
    }
    return best === Infinity ? null : best;
  }

  _drawPlayer(ctx, th) {
    const p = this.player;
    if (!p) return;
    const cx = p.x + p.w / 2;
    const feet = p.y + p.h;
    if (cx < this.camera.x - 120 || cx > this.camera.x + this.viewW + 120) return;
    if (this.fallTimer > 0.62) return;

    // shadow
    const gy = this._findGroundBelow(cx, feet);
    if (gy !== null && gy - feet < 320) {
      const d = clamp(1 - (gy - feet) / 320, 0.1, 1);
      ctx.save();
      ctx.globalAlpha = 0.16 * d;
      ctx.fillStyle = '#4b4540';
      ctx.beginPath();
      ctx.ellipse(cx, gy - 1, 17 * d + 5, 4 * d + 1.4, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // scarf tail
    const tailX = p.tailX ?? cx - 30;
    const tailY = p.tailY ?? p.y + 16;
    ctx.save();
    ctx.strokeStyle = rgba(th.accent, 0.9);
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx, p.y + 20);
    ctx.quadraticCurveTo(cx - p.facing * 16, p.y + 12, tailX, tailY);
    ctx.stroke();
    ctx.strokeStyle = rgba('#f7d2bd', 0.55);
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, p.y + 18);
    ctx.quadraticCurveTo(cx - p.facing * 16, p.y + 10, tailX, tailY - 1);
    ctx.stroke();
    ctx.restore();

    const speedStretch = clamp(-p.vy * 0.00007, -0.05, 0.09);
    const breathe = p.onGround && Math.abs(p.vx) < 20 ? Math.sin(p.idle * 1.5) * 0.015 : 0;
    const sy = clamp(1 - p.squash + speedStretch + breathe, 0.66, 1.32);
    const sx = 1 / sy;

    ctx.save();
    ctx.translate(cx, feet);
    ctx.scale(p.facing * sx, sy);

    const run = p.runPhase;
    const runAmp = p.onGround ? Math.min(1, Math.abs(p.vx) / 240) : 0;
    const legSwing = Math.sin(run) * 5 * runAmp;
    const bodyBob = Math.abs(Math.sin(run)) * 1.8 * runAmp + (p.onGround ? 0 : 1.5);

    // feet
    const footY = -4 - (p.onGround ? 0 : 3);
    ctx.fillStyle = '#d99086';
    ctx.beginPath();
    ctx.ellipse(-8 + legSwing * 0.6, footY - bodyBob, 7, 4.4, -0.1, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(8 - legSwing * 0.6, footY - bodyBob, 7, 4.4, 0.1, 0, TAU);
    ctx.fill();

    // arms
    ctx.fillStyle = '#f3dcc5';
    const armSwing = Math.sin(run + Math.PI) * 4 * runAmp;
    ctx.beginPath();
    ctx.ellipse(-20, -27 - bodyBob - armSwing * 0.4, 4.4, 6.5, -0.25, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(20, -27 - bodyBob + armSwing * 0.4, 4.4, 6.5, 0.25, 0, TAU);
    ctx.fill();

    // body
    const bodyGrad = ctx.createLinearGradient(0, -58, 0, -2);
    bodyGrad.addColorStop(0, '#fffaf0');
    bodyGrad.addColorStop(0.55, '#fbeedb');
    bodyGrad.addColorStop(1, '#f2d7c0');
    ctx.fillStyle = bodyGrad;
    ctx.beginPath();
    ctx.ellipse(0, -31 - bodyBob, 21, 27, 0, 0, TAU);
    ctx.fill();

    // belly
    ctx.fillStyle = 'rgba(255, 250, 239, 0.72)';
    ctx.beginPath();
    ctx.ellipse(0, -22 - bodyBob, 13, 15, 0, 0, TAU);
    ctx.fill();

    // ears
    const earSway = Math.sin(this.time * 1.7) * 0.06 + (p.onGround ? 0 : -0.16);
    ctx.save();
    ctx.translate(0, -50 - bodyBob);
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.rotate(side * (0.18 + earSway) + (side < 0 ? -0.06 : 0.06));
      ctx.fillStyle = '#f8e2cc';
      ctx.beginPath();
      ctx.ellipse(side * 9, -14, 7.4, 17, side * 0.12, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(238, 173, 167, 0.65)';
      ctx.beginPath();
      ctx.ellipse(side * 9, -14, 3.6, 11, side * 0.12, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

    // face
    const look = p.facing * 1.4;
    const blinking = p.blinkTime > 0;
    ctx.strokeStyle = '#6b5359';
    ctx.fillStyle = '#6b5359';
    ctx.lineWidth = 1.9;
    ctx.lineCap = 'round';
    if (blinking) {
      for (const ex of [-7.5, 7.5]) {
        ctx.beginPath();
        ctx.arc(ex + look * 0.4, -34 - bodyBob, 2.6, 0.15, Math.PI - 0.15);
        ctx.stroke();
      }
    } else {
      for (const ex of [-7.5, 7.5]) {
        ctx.beginPath();
        ctx.ellipse(ex + look, -34 - bodyBob, 2.6, 3.2, 0, 0, TAU);
        ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.beginPath();
        ctx.arc(ex + look - 0.8, -35.2 - bodyBob, 0.9, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#6b5359';
      }
    }

    // cheeks
    ctx.fillStyle = 'rgba(238, 158, 154, 0.4)';
    ctx.beginPath();
    ctx.ellipse(-13, -27 - bodyBob, 4.4, 2.6, 0, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(13, -27 - bodyBob, 4.4, 2.6, 0, 0, TAU);
    ctx.fill();

    // smile
    ctx.strokeStyle = 'rgba(107, 83, 89, 0.75)';
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.arc(look * 0.6, -28 - bodyBob, 2.2, 0.25, Math.PI - 0.25);
    ctx.stroke();

    // scarf collar
    ctx.strokeStyle = rgba(th.accent, 0.95);
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.arc(0, -45 - bodyBob, 11, 0.15, Math.PI - 0.15);
    ctx.stroke();
    ctx.restore();

    // little glints around when double-jumping
    if (!p.onGround && p.jumpsUsed >= 2 && p.vy > -700) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (let i = 0; i < 3; i++) {
        const yy = p.y + 10 + i * 9 + Math.sin(this.time * 4 + i) * 2;
        ctx.fillStyle = rgba('#ffeec4', 0.3 - i * 0.07);
        ctx.beginPath();
        ctx.arc(cx + Math.sin(this.time * 3 + i) * 8, yy, 1.8, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }

  _drawWeather(ctx, w, h) {
    const th = this.levelDef.theme;
    if (th.ambient.rain > 0.05) {
      ctx.save();
      ctx.strokeStyle = `rgba(226, 234, 244, ${0.1 + th.ambient.rain * 0.12})`;
      ctx.lineWidth = 1;
      for (let i = 0; i < 62; i++) {
        const sx = (hash(i * 2.3) * w + this.time * (12 + (i % 4) * 8) + Math.sin(this.time + i) * 8) % (w + 60) - 30;
        const sy = (hash(i * 5.1) * h + this.time * (240 + (i % 5) * 60)) % (h + 40) - 20;
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx - 3, sy + 14);
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  _drawVignette(ctx, w, h) {
    const g = ctx.createRadialGradient(w / 2, h * 0.46, Math.min(w, h) * 0.28, w / 2, h * 0.5, Math.max(w, h) * 0.72);
    g.addColorStop(0, 'rgba(70, 48, 58, 0)');
    g.addColorStop(0.72, 'rgba(70, 48, 58, 0.04)');
    g.addColorStop(1, 'rgba(62, 42, 54, 0.26)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    if (this.levelDef.theme.stars > 0.2) {
      const top = ctx.createLinearGradient(0, 0, 0, h * 0.4);
      top.addColorStop(0, 'rgba(28, 32, 60, 0.2)');
      top.addColorStop(1, 'rgba(28, 32, 60, 0)');
      ctx.fillStyle = top;
      ctx.fillRect(0, 0, w, h * 0.4);
    }
  }

  _drawRespawnFade(ctx, w, h) {
    if (this.fallTimer <= 0) return;
    const t = this.fallTimer;
    const alpha = t > 0.42 ? clamp((1.0 - t) / 0.58, 0, 1) : clamp(t / 0.42, 0, 1);
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, Math.max(w, h) * 0.7);
    g.addColorStop(0, `rgba(255, 247, 231, ${alpha * 0.92})`);
    g.addColorStop(1, `rgba(252, 231, 208, ${alpha * 0.98})`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    if (alpha > 0.2) {
      ctx.fillStyle = `rgba(125, 92, 100, ${alpha * 0.5})`;
      ctx.textAlign = 'center';
      ctx.font = 'italic 18px Georgia, serif';
      ctx.fillText('softly back again', w / 2, h / 2 + 6);
    }
  }

  _drawMenuSparkles(ctx, w, h) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 5; i++) {
      const x = w * (0.24 + 0.52 * hash(i * 3.3)) + Math.sin(this.time * 0.2 + i) * 20;
      const y = h * (0.3 + 0.35 * hash(i * 5.7)) + Math.cos(this.time * 0.17 + i * 2) * 16;
      const a = 0.25 + 0.2 * Math.sin(this.time * 0.9 + i * 1.5);
      const g = ctx.createRadialGradient(x, y, 0, x, y, 6);
      g.addColorStop(0, `rgba(255, 246, 214, ${a})`);
      g.addColorStop(1, 'rgba(255, 246, 214, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, 6, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
}

import { Game } from './game.js';
import { AudioEngine } from './audio.js';
import { LEVELS } from './levels.js';
import { clamp } from './util.js';

const $ = (id) => document.getElementById(id);
const SAVE_KEY = 'lumen-hollow-save-v1';

const startScreen = $('startScreen');
const pauseScreen = $('pauseScreen');
const settingsScreen = $('settingsScreen');
const completeScreen = $('completeScreen');
const hud = $('hud');
const touchControls = $('touchControls');
const levelCard = $('levelCard');
const levelName = $('levelName');
const levelChapter = $('levelChapter');
const toast = $('toast');
const countEl = $('count');
const totalEl = $('total');
const startBtn = $('startBtn');
const continueHint = $('continueHint');
const freshBtn = $('freshBtn');
const pauseBtn = $('pauseBtn');
const resumeBtn = $('resumeBtn');
const restartBtn = $('restartBtn');
const settingsBtn = $('settingsBtn');
const menuBtn = $('menuBtn');
const closeSettingsBtn = $('closeSettingsBtn');
const musicRange = $('musicRange');
const sfxRange = $('sfxRange');
const musicValue = $('musicValue');
const sfxValue = $('sfxValue');
const muteBtn = $('muteBtn');
const muteLabel = $('muteLabel');
const soundBtnStart = $('soundBtnStart');
const nextBtn = $('nextBtn');
const completeMenuBtn = $('completeMenuBtn');
const completeTitle = $('completeTitle');
const completeSub = $('completeSub');
const completeCount = $('completeCount');

// ------------------------------------------------------------------ save
const defaultSave = () => ({
  v: 1,
  unlocked: 0,
  current: 0,
  completed: [],
  stars: {},
  checkpoints: {},
  settings: { music: 0.62, sfx: 0.78, muted: false },
});

function loadSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return defaultSave();
    const data = JSON.parse(raw);
    const base = defaultSave();
    const s = {
      ...base,
      ...data,
      settings: { ...base.settings, ...(data.settings || {}) },
      stars: data.stars && typeof data.stars === 'object' ? data.stars : {},
      checkpoints: data.checkpoints && typeof data.checkpoints === 'object' ? data.checkpoints : {},
      completed: Array.isArray(data.completed) ? data.completed : [],
    };
    s.unlocked = clamp(Number(s.unlocked) || 0, 0, LEVELS.length - 1);
    s.current = clamp(Number(s.current) || 0, 0, LEVELS.length - 1);
    return s;
  } catch {
    return defaultSave();
  }
}

let save = loadSave();
let saveTimer = 0;
function persist() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(save));
    } catch {
      /* storage may be unavailable; the game still plays */
    }
  }, 120);
}

function hasProgress() {
  if (save.unlocked > 0) return true;
  if (save.current > 0) return true;
  if (save.completed.length) return true;
  return Object.values(save.stars).some((arr) => Array.isArray(arr) && arr.length)
    || Object.values(save.checkpoints).some((v) => typeof v === 'number' && v >= 0);
}

// ------------------------------------------------------------------ audio
const audio = new AudioEngine();

function applyVolumes() {
  audio.setVolumes({ music: save.settings.music, sfx: save.settings.sfx });
  audio.setMuted(save.settings.muted);
}

let audioStarted = false;
function ensureAudio() {
  audio.init();
  if (!audioStarted) {
    audioStarted = true;
    applyVolumes();
  }
}

// ------------------------------------------------------------------ game
const game = new Game(document.getElementById('game'), audio, {
  onLevelStart(index) {
    save.current = index;
    persist();
    const def = LEVELS[index];
    levelName.textContent = def.name;
    levelChapter.textContent = def.chapter;
    showLevelCard();
    hideComplete();
    setPlayingUI(true);
    updateHud(game.collectedCount, game.starsTotal);
  },
  onHud(count, total) {
    updateHud(count, total);
  },
  onCollect(levelIndex, starId, count, total) {
    if (!Array.isArray(save.stars[levelIndex])) save.stars[levelIndex] = [];
    if (!save.stars[levelIndex].includes(starId)) save.stars[levelIndex].push(starId);
    updateHud(count, total, true);
    persist();
  },
  onCheckpoint(levelIndex, cpIndex) {
    save.checkpoints[levelIndex] = cpIndex;
    persist();
  },
  onGate() {
    persist();
  },
  onComplete(info) {
    onLevelComplete(info);
  },
  onToast(message) {
    showToast(message);
  },
});

// ------------------------------------------------------------------ UI helpers
function setOverlay(el, on) {
  el.classList.toggle('show', on);
  el.setAttribute('aria-hidden', on ? 'false' : 'true');
}

function setPlayingUI(on) {
  hud.classList.toggle('hidden', !on);
  if (!on) touchControls.classList.add('hidden');
  else updateTouchVisibility();
}

function updateTouchVisibility() {
  const touch = matchMedia('(pointer: coarse)').matches || document.body.classList.contains('touch-mode');
  if (game.mode === 'play' && touch) touchControls.classList.remove('hidden');
  else touchControls.classList.add('hidden');
}

function updateHud(count, total, pop = false) {
  countEl.textContent = String(count);
  totalEl.textContent = `/ ${total}`;
  if (pop) {
    hud.querySelector('.hud-pill').classList.remove('pop');
    void hud.querySelector('.hud-pill').offsetWidth;
    hud.querySelector('.hud-pill').classList.add('pop');
  }
}

let toastTimer = 0;
function showToast(message) {
  toast.textContent = message;
  toast.classList.remove('hidden');
  requestAnimationFrame(() => toast.classList.add('show'));
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    toast.classList.remove('show');
    setTimeout(() => toast.classList.add('hidden'), 450);
  }, 2600);
}

let cardTimer = 0;
function showLevelCard() {
  levelCard.classList.remove('hidden');
  requestAnimationFrame(() => levelCard.classList.add('show'));
  clearTimeout(cardTimer);
  cardTimer = setTimeout(() => {
    levelCard.classList.remove('show');
    setTimeout(() => levelCard.classList.add('hidden'), 1300);
  }, 3200);
}

let completeTimer = 0;
let lastComplete = null;

function updateContinueUI() {
  const progress = hasProgress();
  continueHint.classList.toggle('hidden', !progress);
}

function goMenu() {
  clearTimeout(completeTimer);
  setOverlay(pauseScreen, false);
  setOverlay(settingsScreen, false);
  setOverlay(completeScreen, false);
  hideComplete();
  game.attract(save.current);
  game.mode = 'menu';
  setPlayingUI(false);
  lastComplete = null;
  updateContinueUI();
  setOverlay(startScreen, true);
  countEl.textContent = '0';
  game.input.axis = 0;
  game.input.jumpHeld = false;
}

function startGame(index, restore) {
  ensureAudio();
  audio.click();
  clearTimeout(completeTimer);
  const idx = clamp(index, 0, LEVELS.length - 1);
  if (!restore) {
    save.stars[idx] = [];
    save.checkpoints[idx] = -1;
  }
  save.current = idx;
  persist();
  hideComplete();
  setOverlay(startScreen, false);
  setOverlay(pauseScreen, false);
  setOverlay(settingsScreen, false);
  setOverlay(completeScreen, false);
  game.startLevel(idx, {
    restore,
    collected: restore ? save.stars[idx] || [] : [],
    checkpoint: restore ? (typeof save.checkpoints[idx] === 'number' ? save.checkpoints[idx] : -1) : -1,
  });
  setPlayingUI(true);
  updateContinueUI();
}

// ------------------------------------------------------------------ start
function onStart() {
  ensureAudio();
  audio.click();
  if (hasProgress()) {
    startGame(save.current, true);
  } else {
    startGame(0, false);
  }
}

startBtn.addEventListener('click', onStart);

freshBtn.addEventListener('click', () => {
  ensureAudio();
  audio.click();
  const settings = save.settings;
  save = defaultSave();
  save.settings = settings;
  persist();
  updateContinueUI();
  showToast('a fresh little journey');
});

soundBtnStart.addEventListener('click', () => {
  ensureAudio();
  audio.click();
  openSettings('start');
});

// ------------------------------------------------------------------ pause
function openPause() {
  if (game.mode !== 'play') return;
  game.pause();
  setOverlay(pauseScreen, true);
  setPlayingUI(false);
  audio.click();
}

function resumeGame() {
  if (game.mode !== 'paused') return;
  setOverlay(pauseScreen, false);
  setOverlay(settingsScreen, false);
  game.resume();
  setPlayingUI(true);
  audio.click();
}

pauseBtn.addEventListener('click', () => {
  ensureAudio();
  if (game.mode === 'play') openPause();
});
resumeBtn.addEventListener('click', resumeGame);

restartBtn.addEventListener('click', () => {
  ensureAudio();
  clearTimeout(completeTimer);
  setOverlay(pauseScreen, false);
  setOverlay(settingsScreen, false);
  game.restartLevel();
  save.stars[game.levelIndex] = [];
  save.checkpoints[game.levelIndex] = -1;
  persist();
  updateHud(0, game.starsTotal);
  setPlayingUI(true);
  audio.click();
});

menuBtn.addEventListener('click', () => {
  audio.click();
  goMenu();
});

// ------------------------------------------------------------------ settings
let settingsReturn = 'pause';

function syncSettingsUI() {
  const m = Math.round(save.settings.music * 100);
  const s = Math.round(save.settings.sfx * 100);
  musicRange.value = String(m);
  sfxRange.value = String(s);
  musicValue.textContent = String(m);
  sfxValue.textContent = String(s);
  muteBtn.classList.toggle('muted', save.settings.muted);
  muteBtn.setAttribute('aria-pressed', save.settings.muted ? 'true' : 'false');
  muteLabel.textContent = save.settings.muted ? 'sound is resting' : 'mute everything';
}

function openSettings(from) {
  settingsReturn = from;
  syncSettingsUI();
  setOverlay(settingsScreen, true);
  if (from === 'pause') setOverlay(pauseScreen, false);
  if (from === 'start') setOverlay(startScreen, true);
  audio.click();
}

function closeSettings() {
  setOverlay(settingsScreen, false);
  if (settingsReturn === 'pause' && game.mode === 'paused') setOverlay(pauseScreen, true);
  else if (settingsReturn === 'start') setOverlay(startScreen, true);
  audio.click();
}

settingsBtn.addEventListener('click', () => {
  ensureAudio();
  openSettings('pause');
});
closeSettingsBtn.addEventListener('click', closeSettings);

musicRange.addEventListener('input', () => {
  save.settings.music = Number(musicRange.value) / 100;
  musicValue.textContent = musicRange.value;
  audio.setVolumes({ music: save.settings.music });
  persist();
});
sfxRange.addEventListener('input', () => {
  save.settings.sfx = Number(sfxRange.value) / 100;
  sfxValue.textContent = sfxRange.value;
  audio.setVolumes({ sfx: save.settings.sfx });
  persist();
});
muteBtn.addEventListener('click', () => {
  save.settings.muted = !save.settings.muted;
  audio.setMuted(save.settings.muted);
  syncSettingsUI();
  persist();
  if (!save.settings.muted) audio.click();
});

// ------------------------------------------------------------------ complete
function onLevelComplete(info) {
  lastComplete = info;
  save.completed = Array.from(new Set([...save.completed, info.levelIndex]));
  save.unlocked = Math.max(save.unlocked, Math.min(LEVELS.length - 1, info.levelIndex + 1));
  save.stars[info.levelIndex] = game.stars.filter((s) => s.collected).map((s) => s.id);
  if (!info.isLast) save.current = info.levelIndex + 1;
  persist();

  setPlayingUI(false);
  setOverlay(completeScreen, false);
  completeTitle.textContent = info.isLast ? 'a soft little ending' : 'level complete';
  completeSub.textContent = info.isLast
    ? 'the hollow is quiet and warm. thank you for wandering.'
    : 'the fireflies settle around you';
  completeCount.textContent = `${info.collected} / ${info.total}`;
  nextBtn.textContent = info.isLast ? 'back to the meadow' : 'wander onward';
  completeMenuBtn.classList.toggle('hidden', info.isLast);

  clearTimeout(completeTimer);
  completeTimer = setTimeout(() => {
    setOverlay(completeScreen, true);
    audio.click();
  }, 900);
}

nextBtn.addEventListener('click', () => {
  if (!lastComplete) return;
  if (lastComplete.isLast) {
    goMenu();
    return;
  }
  startGame(lastComplete.levelIndex + 1, false);
  lastComplete = null;
});

completeMenuBtn.addEventListener('click', goMenu);

function hideComplete() {
  setOverlay(completeScreen, false);
}

// ------------------------------------------------------------------ input
const keys = new Set();
let touchLeft = false;
let touchRight = false;

function refreshAxis() {
  const left = keys.has('ArrowLeft') || keys.has('KeyA') || touchLeft;
  const right = keys.has('ArrowRight') || keys.has('KeyD') || touchRight;
  game.setAxis((right ? 1 : 0) - (left ? 1 : 0));
}

function isJumpKey(code) {
  return code === 'Space' || code === 'ArrowUp' || code === 'KeyW' || code === 'KeyZ' || code === 'KeyJ';
}

window.addEventListener('keydown', (e) => {
  if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space'].includes(e.code)) e.preventDefault();

  if (e.code === 'Enter' && startScreen.classList.contains('show')) {
    onStart();
    return;
  }
  if (e.code === 'Escape' || e.code === 'KeyP') {
    if (settingsScreen.classList.contains('show')) {
      closeSettings();
    } else if (game.mode === 'play') {
      openPause();
    } else if (game.mode === 'paused') {
      resumeGame();
    }
    return;
  }
  if (e.code === 'KeyM') {
    ensureAudio();
    save.settings.muted = !save.settings.muted;
    audio.setMuted(save.settings.muted);
    syncSettingsUI();
    persist();
    if (game.mode === 'play') showToast(save.settings.muted ? 'sound is resting' : 'sound returns');
    return;
  }

  if (game.mode !== 'play') return;
  if (e.repeat) return;

  keys.add(e.code);
  if (isJumpKey(e.code)) {
    ensureAudio();
    game.queueJump();
    game.setJumpHeld(true);
  }
  refreshAxis();
});

window.addEventListener('keyup', (e) => {
  keys.delete(e.code);
  if (isJumpKey(e.code)) game.setJumpHeld(false);
  refreshAxis();
});

window.addEventListener('blur', () => {
  keys.clear();
  touchLeft = touchRight = false;
  game.setAxis(0);
  game.setJumpHeld(false);
  if (game.mode === 'play') openPause();
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    if (game.mode === 'play') openPause();
  }
});

// touch
function bindTouchButton(btn) {
  const act = btn.dataset.act;
  const press = (e) => {
    e.preventDefault();
    ensureAudio();
    btn.classList.add('active');
    if (btn.setPointerCapture && e.pointerId !== undefined) {
      try { btn.setPointerCapture(e.pointerId); } catch { /* noop */ }
    }
    if (act === 'left') {
      touchLeft = true;
      refreshAxis();
    } else if (act === 'right') {
      touchRight = true;
      refreshAxis();
    } else if (act === 'jump') {
      game.queueJump();
      game.setJumpHeld(true);
    }
  };
  const release = (e) => {
    if (e) e.preventDefault();
    btn.classList.remove('active');
    if (act === 'left') {
      touchLeft = false;
      refreshAxis();
    } else if (act === 'right') {
      touchRight = false;
      refreshAxis();
    } else if (act === 'jump') {
      game.setJumpHeld(false);
    }
  };
  btn.addEventListener('pointerdown', press);
  btn.addEventListener('pointerup', release);
  btn.addEventListener('pointercancel', release);
  btn.addEventListener('lostpointercapture', release);
  btn.addEventListener('contextmenu', (e) => e.preventDefault());
}
document.querySelectorAll('.touch-btn').forEach(bindTouchButton);

document.addEventListener('touchstart', () => {
  document.body.classList.add('touch-mode');
  if (game.mode === 'play') updateTouchVisibility();
}, { passive: true, once: true });

// click chime for UI
document.querySelectorAll('button').forEach((btn) => {
  btn.addEventListener('pointerdown', () => ensureAudio(), { passive: true });
});

// pause automatically if the page loses focus while playing
window.addEventListener('pagehide', () => {
  persist();
});

// resume the audio context on any gesture
window.addEventListener('pointerdown', ensureAudio, { once: true });
window.addEventListener('keydown', ensureAudio, { once: true });

// ------------------------------------------------------------------ boot
function boot() {
  applyVolumes();
  syncSettingsUI();
  updateContinueUI();
  setPlayingUI(false);
  updateHud(0, LEVELS[0].stars.length);
  totalEl.textContent = `/ ${LEVELS[0].stars.length}`;

  // preload / init audio only after a gesture; the menu music starts then.
  const savedLevel = save.current;
  game.attract(savedLevel);
  game.mode = 'menu';
  startBtn.textContent = 'tap to start';

  // tiny debug handle for tests and tinkering
  window.__lumen = {
    game,
    audio,
    get save() { return save; },
    levels: LEVELS,
    startLevel: (i) => startGame(i, false),
    gotoMenu: goMenu,
    state: () => game.debugState(),
  };
}

boot();

// keep the sliders in sync if settings change elsewhere
window.addEventListener('storage', (e) => {
  if (e.key === SAVE_KEY) {
    save = loadSave();
    applyVolumes();
    syncSettingsUI();
    updateContinueUI();
  }
});

