const fs = require('fs');
const path = require('path');
const runtime = path.join(process.env.HOME, '.local/share/omgithub-playwright');
const { chromium } = require(path.join(runtime, 'node_modules/playwright'));
const config = JSON.parse(fs.readFileSync(path.join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY = process.env.DISPLAY || ':' + fs.readFileSync(path.join(runtime, 'display'), 'utf8').trim();

const out = path.join(process.cwd(), 'screenshots');
fs.mkdirSync(out, { recursive: true });
const shot = async (page, name) => {
  await page.screenshot({ path: path.join(out, name + '.jpg'), type: 'jpeg', quality: 72 });
  console.log('shot', name);
};

(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
  await page.waitForTimeout(2200);
  await shot(page, 'menu');
  console.log('state menu', await page.evaluate(() => window.__lumen.state()));

  await page.click('#startBtn');
  await page.waitForTimeout(1600);
  await shot(page, 'level1-start');
  console.log('state start', await page.evaluate(() => window.__lumen.state()));

  await page.keyboard.down('ArrowRight');
  await page.waitForTimeout(900);
  await page.keyboard.press('Space');
  await page.waitForTimeout(900);
  await page.keyboard.press('Space');
  await page.waitForTimeout(1200);
  await page.keyboard.up('ArrowRight');
  await page.waitForTimeout(500);
  await shot(page, 'level1-move');
  console.log('state moved', await page.evaluate(() => window.__lumen.state()));

  console.log('errors', JSON.stringify(errors, null, 2));
  await browser.close();
})();

