const fs=require('fs'), path=require('path');
const runtime=path.join(process.env.HOME,'.local/share/omgithub-playwright');
const {chromium}=require(path.join(runtime,'node_modules/playwright'));
const config=JSON.parse(fs.readFileSync(path.join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY=process.env.DISPLAY||':'+fs.readFileSync(path.join(runtime,'display'),'utf8').trim();
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions, args:[...config.browser.launchOptions.args,'--disable-background-timer-throttling','--disable-renderer-backgrounding','--disable-backgrounding-occluded-windows','--disable-features=CalculateNativeWinOcclusion'], timeout:30000});
 const page=await browser.newPage({viewport:{width:1200,height:750},deviceScaleFactor:1});
 await page.goto('http://localhost:3002/',{waitUntil:'load'});
 await page.bringToFront();
 await page.waitForTimeout(1000);
 await page.evaluate(() => { window.__frames=0; const t=performance.now(); function f(){ window.__frames++; if(performance.now()-t<2500) requestAnimationFrame(f);} requestAnimationFrame(f); window.__t=t; });
 await page.waitForTimeout(3000);
 console.log('fps', await page.evaluate(()=>window.__frames/((performance.now()-window.__t)/1000)));
 await browser.close();
})();
