      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createLinearGradient(cx, baseY, cx, topY - 40);
      g.addColorStop(0, rgba('#ffe7ae', 0.1 + gate.glow * 0.14));
      g.addColorStop(0.6, rgba('#ffe7ae', 0.18 * gate.glow));
