const fs=require('fs'), path=require('path');
const runtime=path.join(process.env.HOME,'.local/share/omgithub-playwright');
const {chromium}=require(path.join(runtime,'node_modules/playwright'));
const config=JSON.parse(fs.readFileSync(path.join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY=process.env.DISPLAY||':'+fs.readFileSync(path.join(runtime,'display'),'utf8').trim();
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions, timeout:30000});
 const page=await browser.newPage({viewport:{width:1200,height:750},deviceScaleFactor:1});
 const errs=[]; page.on('pageerror',e=>errs.push(e.message)); page.on('console',m=>{if(m.type()==='error')errs.push(m.text())});
 await page.goto('http://localhost:3002/',{waitUntil:'load'});
 await page.waitForTimeout(800);
 await page.click('#startBtn');
 await page.waitForTimeout(400);
 const results = await page.evaluate(async () => {
   const out=[];
   for (let li=0; li<5; li++) {
     const g=window.__lumen.game;
     window.__lumen.startLevel(li);
     g.input.axis=1; g.input.jumpHeld=true;
     let maxX=0, fell=0, last=0;
     for(let i=0;i<120*50 && g.mode==='play';i++){
       if(i%18===0){ g.queueJump(); g.input.jumpHeld=true; }
       g._step(1/120);
       if(g.player) maxX=Math.max(maxX,g.player.x);
       if(g.fallTimer>0) fell++;
       last=g;
     }
     out.push({level:li, mode:g.mode, maxX:Math.round(maxX), goal:g.goal.x, collected:g.collectedCount, total:g.starsTotal, fellSteps:fell, gate:g.gate&&{u:g.gate.unlocked,open:g.gate.open}});
   }
   return out;
 });
 console.log(JSON.stringify(results,null,2));
 console.log('errors',errs);
 await browser.close();
})();
