const out=path.join(process.cwd(),'screenshots'); fs.mkdirSync(out,{recursive:true});
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions, timeout:30000});
 const page=await browser.newPage({viewport:{width:1200,height:750},deviceScaleFactor:1});
 const errs=[]; page.on('pageerror',e=>errs.push(e.message)); page.on('console',m=>{if(m.type()==='error')errs.push(m.text())});
 await page.goto('http://localhost:3002/',{waitUntil:'load'});
 await page.waitForTimeout(800);
 await page.screenshot({path:path.join(out,'menu2.jpg'),type:'jpeg',quality:72});
 await page.click('#startBtn');
 await page.waitForTimeout(500);
 await page.evaluate(()=>{document.getElementById('levelCard').classList.add('hidden');});
 const place = async (level, x, y, name) => {
   await page.evaluate(({level,x,y})=>{
     const L=window.__lumen; L.startLevel(level);
     const g=L.game; g.player.x=x; g.player.y=y-42; g.player.vx=0; g.player.vy=0;
     g.camera.x=Math.max(0,Math.min(g.level.width-g.viewW, x-g.viewW/2));
     g.camera.y=Math.max(0,Math.min(g.level.height-g.viewH, y-42+21-g.viewH*0.56));
     document.getElementById('levelCard').classList.add('hidden');
   },{level,x,y});
   await page.waitForTimeout(450);
   await page.evaluate(()=>{document.getElementById('levelCard').classList.add('hidden');});
   await page.screenshot({path:path.join(out,name+'.jpg'),type:'jpeg',quality:72});
   console.log('shot',name, await page.evaluate(()=>window.__lumen.state()));
 };
 await place(0, 600, 760, 'lv1');
 await place(1, 2500, 700, 'lv2');
 await place(2, 1950, 720, 'lv3');
 await place(3, 3100, 680, 'lv4');
 await place(4, 3820, 780, 'lv5-gate');
 // open the gate by gathering everything, then show the goal
 await page.evaluate(()=>{
   const g=window.__lumen.game;
   g.stars.forEach(s=>{ if(!s.collected){ s.collected=true; g.collectedCount++; }});
   g._openGate();
   g.player.x=4380; g.player.y=780-42;
   g.camera.x=Math.max(0,Math.min(g.level.width-g.viewW,4380-g.viewW/2));
   g.camera.y=Math.max(0,Math.min(g.level.height-g.viewH,780-42+21-g.viewH*0.56));
   document.getElementById('levelCard').classList.add('hidden');
 });
 await page.waitForTimeout(900);
 await page.screenshot({path:path.join(out,'lv5-open.jpg'),type:'jpeg',quality:72});
 console.log('open state', await page.evaluate(()=>window.__lumen.state()));
 // pause overlay
 await page.evaluate(()=>window.__lumen.startLevel(0));
 await page.waitForTimeout(400);
 await page.click('#pauseBtn');
 await page.waitForTimeout(500);
 await page.screenshot({path:path.join(out,'pause.jpg'),type:'jpeg',quality:72});
 // settings
 await page.click('#settingsBtn');
 await page.waitForTimeout(500);
 await page.screenshot({path:path.join(out,'settings.jpg'),type:'jpeg',quality:72});
 await page.click('#closeSettingsBtn');
 await page.click('#resumeBtn');
 // complete overlay
 await page.evaluate(()=>{
   const g=window.__lumen.game;
   g.player.x=g.goal.x-15; g.player.y=g.goal.y-44; g.step&&g.step;
   g._step(1/120);
 });
 await page.waitForTimeout(1600);
 await page.screenshot({path:path.join(out,'complete.jpg'),type:'jpeg',quality:72});
 console.log('complete state', await page.evaluate(()=>window.__lumen.state()));
 console.log('errors', errs);
 // mobile
 const ctx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,isMobile:true,hasTouch:true});
 const mp=await ctx.newPage();
 mp.on('pageerror',e=>errs.push('mobile '+e.message));
 await mp.goto('http://localhost:3002/',{waitUntil:'load'});
 await mp.waitForTimeout(800);
 await mp.screenshot({path:path.join(out,'mobile-menu.jpg'),type:'jpeg',quality:72});
 await mp.tap('#startBtn');
 await mp.waitForTimeout(900);
 await mp.evaluate(()=>{document.getElementById('levelCard').classList.add('hidden');});
 await mp.screenshot({path:path.join(out,'mobile-play.jpg'),type:'jpeg',quality:72});
 console.log('mobile state', await mp.evaluate(()=>({state:window.__lumen.state(), touch:!document.getElementById('touchControls').classList.contains('hidden')})));
 console.log('errors all', errs);
 await browser.close();
})();

