const fs=require('fs'), path=require('path');
const runtime=path.join(process.env.HOME,'.local/share/omgithub-playwright');
const {chromium}=require(path.join(runtime,'node_modules/playwright'));
const config=JSON.parse(fs.readFileSync(path.join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY=process.env.DISPLAY||':'+fs.readFileSync(path.join(runtime,'display'),'utf8').trim();
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions,args:[...config.browser.launchOptions.args,'--disable-background-timer-throttling','--disable-renderer-backgrounding','--disable-backgrounding-occluded-windows','--disable-features=CalculateNativeWinOcclusion']});
 const page=await browser.newPage({viewport:{width:1200,height:750},deviceScaleFactor:1});
 await page.goto('http://localhost:3002/',{waitUntil:'load'});
 await page.waitForTimeout(800);
 await page.click('#startBtn');
 await page.waitForTimeout(500);
 async function measure(name, mode){
   await page.evaluate(({mode})=>{
     const g=window.__lumen.game;
     if(!g.__origRender) g.__origRender=g.render.bind(g);
     g.render=()=>{
       const ctx=g.ctx, {cssW:w,cssH:h,dpr,zoom,camera}=g;
