const fs=require('fs'), path=require('path');
const runtime=path.join(process.env.HOME,'.local/share/omgithub-playwright');
const {chromium}=require(path.join(runtime,'node_modules/playwright'));
const config=JSON.parse(fs.readFileSync(path.join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY=process.env.DISPLAY||':'+fs.readFileSync(path.join(runtime,'display'),'utf8').trim();
const results=[]; const errs=[];
function ok(name, cond, extra=''){ results.push({name, pass:!!cond, extra}); if(!cond) console.log('FAIL',name,extra); }
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions, timeout:30000});
 const ctx=await browser.newContext({viewport:{width:1200,height:750}});
 const page=await ctx.newPage();
 page.on('pageerror',e=>errs.push('pageerror: '+e.message));
 page.on('console',m=>{if(m.type()==='error') errs.push('console: '+m.text())});
 await page.goto('http://localhost:3002/',{waitUntil:'load'});
 await page.evaluate(()=>localStorage.clear());
 await page.reload({waitUntil:'load'});
 await page.waitForTimeout(700);
 ok('menu visible', await page.locator('#startScreen').evaluate(e=>e.classList.contains('show')));
 ok('hud hidden', await page.locator('#hud').evaluate(e=>e.classList.contains('hidden')));
 await page.click('#startBtn');
 await page.waitForTimeout(600);
 let st=await page.evaluate(()=>window.__lumen.state());
 ok('gameplay started', st.mode==='play' && st.level===0, JSON.stringify(st));
 ok('hud visible', await page.locator('#hud').evaluate(e=>!e.classList.contains('hidden')));
 const x0=st.x;
 await page.keyboard.down('ArrowRight'); await page.waitForTimeout(900); await page.keyboard.up('ArrowRight');
 st=await page.evaluate(()=>window.__lumen.state());
 ok('arrow moves right', st.x>x0+25, `x ${x0}->${st.x}`);
 const y0=st.y;
 await page.keyboard.down('Space'); await page.waitForTimeout(160); await page.keyboard.up('Space');
 await page.waitForTimeout(120);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('space jumps', st.y<y0-20, `y ${y0}->${st.y}`);
 await page.keyboard.down('Space'); await page.waitForTimeout(90); await page.keyboard.up('Space');
 await page.waitForTimeout(200);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('double jump works', st.jumpsUsed>=1, JSON.stringify({vy:st.vy,jumps:st.jumpsUsed}));
 await page.waitForTimeout(800);
 await page.keyboard.press('Escape'); await page.waitForTimeout(350);
 ok('escape pauses', await page.evaluate(()=>window.__lumen.game.mode==='paused'));
 ok('pause overlay', await page.locator('#pauseScreen').evaluate(e=>e.classList.contains('show')));
 await page.click('#settingsBtn'); await page.waitForTimeout(300);
 ok('settings overlay', await page.locator('#settingsScreen').evaluate(e=>e.classList.contains('show')));
 await page.locator('#musicRange').fill('37'); await page.waitForTimeout(150);
 await page.click('#muteBtn'); await page.waitForTimeout(150);
 let saved=await page.evaluate(()=>({music:window.__lumen.save.settings.music,muted:window.__lumen.save.settings.muted,label:document.getElementById('muteLabel').textContent}));
 ok('settings change saved', Math.abs(saved.music-0.37)<0.001 && saved.muted===true, JSON.stringify(saved));
 await page.click('#closeSettingsBtn'); await page.waitForTimeout(250);
 ok('settings returns to pause', await page.locator('#pauseScreen').evaluate(e=>e.classList.contains('show')));
 await page.click('#resumeBtn'); await page.waitForTimeout(300);
 ok('resume works', await page.evaluate(()=>window.__lumen.game.mode==='play'));
 // collect a star via overlap
 await page.evaluate(()=>{const g=window.__lumen.game; const s=g.stars.find(s=>!s.collected); g.player.x=s.x-15; g.player.y=s.y-21;});
 await page.waitForTimeout(400);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('star collected', st.collected>=1, JSON.stringify({collected:st.collected}));
 await page.waitForTimeout(300);
 saved=await page.evaluate(()=>({stars:window.__lumen.save.stars[0]||[], current:window.__lumen.save.current}));
 ok('star persisted', saved.stars.length>=1 && saved.current===0, JSON.stringify(saved));
 // fall into gap between ground blocks
 await page.evaluate(()=>{const g=window.__lumen.game; g.player.x=930; g.player.y=300; g.player.vy=0;});
 await page.waitForTimeout(2200);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('gentle respawn', st.mode==='play' && st.y<760, JSON.stringify(st));
 // pause/restart
 await page.keyboard.press('Escape'); await page.waitForTimeout(200);
 await page.click('#restartBtn'); await page.waitForTimeout(500);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('restart resets stars', st.collected===0 && st.mode==='play', JSON.stringify(st));
 // finish level
 await page.evaluate(()=>{const g=window.__lumen.game; g.player.x=g.goal.x-10; g.player.y=g.goal.y-44;});
 await page.waitForTimeout(1400);
 ok('complete overlay appears', await page.locator('#completeScreen').evaluate(e=>e.classList.contains('show')));
 ok('completion saved', await page.evaluate(()=>window.__lumen.save.completed.includes(0)));
 await page.click('#nextBtn'); await page.waitForTimeout(700);
 st=await page.evaluate(()=>window.__lumen.state());
 ok('next level starts', st.level===1 && st.mode==='play', JSON.stringify(st));
 // reload persistence
 await page.waitForTimeout(300);
 const pre=await page.evaluate(()=>window.__lumen.save);
 await page.reload({waitUntil:'load'}); await page.waitForTimeout(800);
 const post=await page.evaluate(()=>({save:window.__lumen.save, hint:!document.getElementById('continueHint').classList.contains('hidden'), start:document.getElementById('startBtn').textContent}));
 ok('progress survives reload', post.save.current===1 && post.save.completed.includes(0), JSON.stringify({current:post.save.current,completed:post.save.completed}));
 ok('continue hint shown', post.hint, JSON.stringify(post.start));
 // mobile touch
 const mctx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,isMobile:true,hasTouch:true});
 const mp=await mctx.newPage();
 mp.on('pageerror',e=>errs.push('mobile pageerror: '+e.message));
 await mp.goto('http://localhost:3002/',{waitUntil:'load'}); await mp.waitForTimeout(700);
 await mp.tap('#startBtn'); await mp.waitForTimeout(700);
 const touchVisible=await mp.locator('#touchControls').evaluate(e=>!e.classList.contains('hidden'));
 ok('touch controls visible', touchVisible);
 const mx0=(await mp.evaluate(()=>window.__lumen.state())).x;
 await mp.evaluate(()=>{const b=document.querySelector('[data-act="right"]'); b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,pointerType:'touch'}));});
 await mp.waitForTimeout(900);
 await mp.evaluate(()=>{const b=document.querySelector('[data-act="right"]'); b.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1,pointerType:'touch'}));});
 const mst=await mp.evaluate(()=>window.__lumen.state());
 ok('touch moves right', mst.x>mx0+15, `x ${mx0}->${mst.x}`);
 const my0=mst.y;
 await mp.evaluate(()=>{const b=document.querySelector('[data-act="jump"]'); b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:2,pointerType:'touch'}));});
 await mp.waitForTimeout(150);
 await mp.evaluate(()=>{const b=document.querySelector('[data-act="jump"]'); b.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:2,pointerType:'touch'}));});
 await mp.waitForTimeout(180);
 const mst2=await mp.evaluate(()=>window.__lumen.state());
 ok('touch jumps', mst2.y<my0-15, `y ${my0}->${mst2.y}`);
 ok('no runtime errors', errs.length===0, errs.join(' | '));
 console.log(JSON.stringify(results,null,2));
 console.log('errors', errs);
 await browser.close();
})().catch(e=>{console.error(e); process.exit(1);});

